export const questions: Question[] = [
  { id: "y2nm4-001", topicRef: "y2nm4", topicTitle: "Newton-Raphson 01", difficulty: "Foundation", answerType: "expression", questionText: "State the Newton-Raphson iterative formula for finding a root of \\(f(x) = 0\\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["formula"], workedSolution: { steps: [ { stepNumber: 1, description: "Write down the iteration.", workingLatex: "x_{n+1} = x_{n} - \\frac{f(x_{n})}{f'(x_{n})}", explanation: "Newton-Raphson refines an estimate \\(x_{n}\\) by subtracting \\(\\displaystyle\\frac{f(x_{n})}{f'(x_{n})}\\) — the value of the function divided by its gradient at that point. The result \\(x_{n+1}\\) is (usually) a better estimate of the root, and the process is repeated." } ], finalAnswer: "\\(x_{n+1} = x_{n} - \\displaystyle\\frac{f(x_{n})}{f'(x_{n})}\\)." } },
  { id: "y2nm4-002", topicRef: "y2nm4", topicTitle: "Newton-Raphson 02", difficulty: "Foundation", answerType: "expression", questionText: "Explain geometrically how each Newton-Raphson step obtains \\(x_{n+1}\\) from \\(x_{n}\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["geometry"], workedSolution: { steps: [ { stepNumber: 1, description: "Draw the tangent at \\(\\left(x_{n}, f(x_{n})\\right)\\).", workingLatex: "", explanation: "Near \\(x_{n}\\) we replace the curve by its tangent line, because a straight line is trivial to solve for its own root. That tangent has gradient \\(f'(x_{n})\\)." }, { stepNumber: 2, description: "Set the tangent's height to zero.", workingLatex: "0 - f(x_{n}) = f'(x_{n})\\left(x_{n+1} - x_{n}\\right)", explanation: "The tangent crosses the x-axis where its \\(y\\)-value is \\(0\\). Using gradient = rise over run between \\(\\left(x_{n}, f(x_{n})\\right)\\) and \\(\\left(x_{n+1}, 0\\right)\\) gives this equation." }, { stepNumber: 3, description: "Rearrange for \\(x_{n+1}\\).", workingLatex: "x_{n+1} = x_{n} - \\frac{f(x_{n})}{f'(x_{n})}", explanation: "Dividing through by \\(f'(x_{n})\\) and adding \\(x_{n}\\) recovers the iteration. So each step slides down the tangent until it meets the axis." } ], finalAnswer: "\\(x_{n+1}\\) is the point where the tangent to \\(y = f(x)\\) at \\(\\left(x_{n}, f(x_{n})\\right)\\) crosses the x-axis." } },
  { id: "y2nm4-003", topicRef: "y2nm4", topicTitle: "Newton-Raphson 03", difficulty: "Foundation", answerType: "expression", questionText: "Apply one step of Newton-Raphson to \\(f(x) = x^{2} - 2\\) starting from \\(x_{0} = 1.5\\). Give \\(x_{1}\\) to 4 decimal places.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["calculation"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate \\(f\\).", workingLatex: "f(x) = x^{2} - 2, \\quad f'(x) = 2x", explanation: "The iteration needs both \\(f\\) and \\(f'\\). Differentiating \\(x^{2} - 2\\) by the power rule gives \\(2x\\)." }, { stepNumber: 2, description: "Evaluate \\(f\\) and \\(f'\\) at \\(x_{0} = 1.5\\).", workingLatex: "f(1.5) = 1.5^{2} - 2 = 0.25, \\quad f'(1.5) = 2(1.5) = 3", explanation: "Substitute the starting value into each expression; these two numbers feed straight into the formula." }, { stepNumber: 3, description: "Substitute into the iteration.", workingLatex: "x_{1} = 1.5 - \\frac{0.25}{3}", explanation: "Apply \\(x_{1} = x_{0} - \\frac{f(x_{0})}{f'(x_{0})}\\) with the values just found." }, { stepNumber: 4, description: "Simplify to 4 d.p.", workingLatex: "x_{1} = 1.5 - 0.08333\\ldots = 1.41666\\ldots \\approx 1.4167", explanation: "Carry the full-accuracy quotient on your calculator and round only at the very end to avoid rounding drift." } ], finalAnswer: "\\(x_{1} \\approx 1.4167\\)." } },
  { id: "y2nm4-004", topicRef: "y2nm4", topicTitle: "Newton-Raphson 04", difficulty: "Foundation", answerType: "expression", questionText: "Continuing Q3, compute \\(x_{2}\\) and \\(x_{3}\\) to 4 decimal places. Compare with \\(\\sqrt{2}\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["calculation"], workedSolution: { steps: [ { stepNumber: 1, description: "Feed \\(x_{1}\\) back into the formula.", workingLatex: "x_{2} = 1.41667 - \\frac{(1.41667)^{2} - 2}{2(1.41667)}", explanation: "Newton-Raphson is recursive: the output \\(x_{1}\\) becomes the input for the next step. Use the unrounded \\(x_{1}\\) from your calculator." }, { stepNumber: 2, description: "Simplify to find \\(x_{2}\\).", workingLatex: "x_{2} = 1.41667 - \\frac{0.00694}{2.83333} \\approx 1.4142", explanation: "The correction is now tiny — a sign the iteration is closing in fast on the root." }, { stepNumber: 3, description: "Compute \\(x_{3}\\).", workingLatex: "x_{3} = 1.41421 - \\frac{(1.41421)^{2} - 2}{2(1.41421)} \\approx 1.4142", explanation: "\\(x_{3}\\) agrees with \\(x_{2}\\) to 4 d.p., so the sequence has effectively converged." }, { stepNumber: 4, description: "Compare with \\(\\sqrt{2}\\).", workingLatex: "\\sqrt{2} = 1.41421\\ldots", explanation: "The estimate matches \\(\\sqrt{2}\\) to 4 d.p. — expected, since the positive root of \\(x^{2} - 2 = 0\\) is exactly \\(\\sqrt{2}\\)." } ], finalAnswer: "\\(x_{2} \\approx 1.4142,\\ x_{3} \\approx 1.4142\\); these match \\(\\sqrt{2} \\approx 1.4142\\)." } },
  { id: "y2nm4-005", topicRef: "y2nm4", topicTitle: "Newton-Raphson 05", difficulty: "Foundation", answerType: "expression", questionText: "Apply one step of Newton-Raphson to \\(f(x) = x^{3} - 7\\) starting from \\(x_{0} = 2\\). Give \\(x_{1}\\) to 4 decimal places.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["calculation"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate \\(f\\).", workingLatex: "f(x) = x^{3} - 7, \\quad f'(x) = 3x^{2}", explanation: "Power rule on \\(x^{3}\\) gives \\(3x^{2}\\); the constant \\(-7\\) differentiates to \\(0\\)." }, { stepNumber: 2, description: "Evaluate at \\(x_{0} = 2\\).", workingLatex: "f(2) = 8 - 7 = 1, \\quad f'(2) = 3(2)^{2} = 12", explanation: "Substituting the start value gives a small positive \\(f\\) and a steep gradient, so we expect only a small correction." }, { stepNumber: 3, description: "Apply the iteration.", workingLatex: "x_{1} = 2 - \\frac{1}{12} = 1.91666\\ldots \\approx 1.9167", explanation: "Subtract \\(\\frac{f(2)}{f'(2)}\\) from the start value. Rounding only at the end gives \\(x_{1} \\approx 1.9167\\)." } ], finalAnswer: "\\(x_{1} \\approx 1.9167\\)." } },
  { id: "y2nm4-006", topicRef: "y2nm4", topicTitle: "Newton-Raphson 06", difficulty: "Foundation", answerType: "expression", questionText: "Continuing Q5, compute \\(x_{2}\\) and \\(x_{3}\\) to 4 decimal places.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["calculation"], workedSolution: { steps: [ { stepNumber: 1, description: "Substitute \\(x_{1}\\) into the formula.", workingLatex: "x_{2} = 1.91667 - \\frac{(1.91667)^{3} - 7}{3(1.91667)^{2}}", explanation: "Reuse the iteration with the previous output. Keep the unrounded \\(x_{1}\\) to preserve accuracy." }, { stepNumber: 2, description: "Simplify to find \\(x_{2}\\).", workingLatex: "x_{2} = 1.91667 - \\frac{0.04116}{11.02083} \\approx 1.9129", explanation: "The numerator \\(f(x_{1})\\) has shrunk a lot, so the correction is small." }, { stepNumber: 3, description: "Compute \\(x_{3}\\).", workingLatex: "x_{3} = 1.91293 - \\frac{(1.91293)^{3} - 7}{3(1.91293)^{2}} \\approx 1.9129", explanation: "\\(x_{3}\\) equals \\(x_{2}\\) to 4 d.p.: the iteration has converged on \\(\\sqrt[3]{7} \\approx 1.9129\\)." } ], finalAnswer: "\\(x_{2} \\approx 1.9129,\\ x_{3} \\approx 1.9129\\) (matching \\(\\sqrt[3]{7}\\))." } },
  { id: "y2nm4-007", topicRef: "y2nm4", topicTitle: "Newton-Raphson 07", difficulty: "Foundation", answerType: "expression", questionText: "Show that the Newton-Raphson iteration for \\(f(x) = x^{2} - k\\) simplifies to \\(x_{n+1} = \\frac{1}{2}\\!\\left(x_{n} + \\frac{k}{x_{n}}\\right)\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["derivation"], workedSolution: { steps: [ { stepNumber: 1, description: "Substitute \\(f\\) and \\(f'\\) into the formula.", workingLatex: "x_{n+1} = x_{n} - \\frac{x_{n}^{2} - k}{2 x_{n}}", explanation: "Here \\(f(x) = x^{2} - k\\) so \\(f'(x) = 2x\\). Putting these into the iteration is the starting point of the proof." }, { stepNumber: 2, description: "Write over a common denominator.", workingLatex: "x_{n+1} = \\frac{2 x_{n}^{2} - \\left(x_{n}^{2} - k\\right)}{2 x_{n}}", explanation: "Combine \\(x_{n}\\) and the fraction over the single denominator \\(2x_{n}\\) so the numerators can be added." }, { stepNumber: 3, description: "Collect terms in the numerator.", workingLatex: "x_{n+1} = \\frac{x_{n}^{2} + k}{2 x_{n}}", explanation: "Expanding the bracket, \\(2x_{n}^{2} - x_{n}^{2} + k = x_{n}^{2} + k\\)." }, { stepNumber: 4, description: "Split the fraction to finish.", workingLatex: "x_{n+1} = \\frac{1}{2}\\!\\left(\\frac{x_{n}^{2}}{x_{n}} + \\frac{k}{x_{n}}\\right) = \\frac{1}{2}\\!\\left(x_{n} + \\frac{k}{x_{n}}\\right)", explanation: "Factoring out \\(\\frac{1}{2x_{n}}\\) and simplifying \\(\\frac{x_{n}^{2}}{x_{n}} = x_{n}\\) gives the required form — the classical 'divide and average' method for square roots." } ], finalAnswer: "Shown: \\(x_{n+1} = \\displaystyle\\frac{1}{2}\\!\\left(x_{n} + \\displaystyle\\frac{k}{x_{n}}\\right)\\)." } },
  { id: "y2nm4-008", topicRef: "y2nm4", topicTitle: "Newton-Raphson 08", difficulty: "Foundation", answerType: "expression", questionText: "Use Newton-Raphson on \\(f(x) = x^{2} - 11\\) with \\(x_{0} = 3\\) to estimate \\(\\sqrt{11}\\) to 4 decimal places.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["calculation"], workedSolution: { steps: [ { stepNumber: 1, description: "Use the square-root iteration from Q7.", workingLatex: "x_{n+1} = \\frac{1}{2}\\!\\left(x_{n} + \\frac{11}{x_{n}}\\right)", explanation: "With \\(k = 11\\) the iteration becomes 'average \\(x_{n}\\) with \\(\\frac{11}{x_{n}}\\)', which is quicker to evaluate than the full formula." }, { stepNumber: 2, description: "Compute \\(x_{1}\\).", workingLatex: "x_{1} = \\frac{1}{2}\\!\\left(3 + \\frac{11}{3}\\right) = \\frac{1}{2}(3 + 3.66667) \\approx 3.3333", explanation: "Substitute \\(x_{0} = 3\\). The two quantities being averaged straddle the true root." }, { stepNumber: 3, description: "Compute \\(x_{2}\\).", workingLatex: "x_{2} = \\frac{1}{2}\\!\\left(3.33333 + \\frac{11}{3.33333}\\right) \\approx 3.3167", explanation: "Feed \\(x_{1}\\) back in. The gap between the two averaged values has narrowed sharply." }, { stepNumber: 4, description: "Compute \\(x_{3}\\) and conclude.", workingLatex: "x_{3} = \\frac{1}{2}\\!\\left(3.31667 + \\frac{11}{3.31667}\\right) \\approx 3.3166", explanation: "\\(x_{3}\\) is stable to 4 d.p., so \\(\\sqrt{11} \\approx 3.3166\\)." } ], finalAnswer: "\\(\\sqrt{11} \\approx 3.3166\\)." } },
  { id: "y2nm4-009", topicRef: "y2nm4", topicTitle: "Newton-Raphson 09", difficulty: "Foundation", answerType: "expression", questionText: "The equation \\(x^{3} - x - 1 = 0\\) has a root near \\(x = 1.3\\). Apply one Newton-Raphson step from \\(x_{0} = 1.3\\) to find \\(x_{1}\\) to 4 decimal places.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["calculation"], workedSolution: { steps: [ { stepNumber: 1, description: "Evaluate \\(f(x_{0})\\).", workingLatex: "f(1.3) = 1.3^{3} - 1.3 - 1 = 2.197 - 2.3 = -0.103", explanation: "A negative value tells us the curve is just below the axis at \\(x = 1.3\\), so the root is slightly to the right." }, { stepNumber: 2, description: "Differentiate and evaluate \\(f'(x_{0})\\).", workingLatex: "f'(x) = 3x^{2} - 1, \\quad f'(1.3) = 3(1.69) - 1 = 4.07", explanation: "The gradient is positive and fairly steep, so the tangent will cross the axis close by." }, { stepNumber: 3, description: "Apply the iteration.", workingLatex: "x_{1} = 1.3 - \\frac{-0.103}{4.07} = 1.3 + 0.02531 \\approx 1.3253", explanation: "Subtracting a negative correction nudges the estimate to the right, exactly as the sign of \\(f\\) predicted." } ], finalAnswer: "\\(x_{1} \\approx 1.3253\\)." } },
  { id: "y2nm4-010", topicRef: "y2nm4", topicTitle: "Newton-Raphson 10", difficulty: "Foundation", answerType: "expression", questionText: "Continuing Q9, compute \\(x_{2}\\) to 4 decimal places and state the root to 3 decimal places.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["calculation"], workedSolution: { steps: [ { stepNumber: 1, description: "Evaluate \\(f\\) and \\(f'\\) at \\(x_{1}\\).", workingLatex: "f(1.32531) \\approx 0.00016, \\quad f'(1.32531) = 3(1.32531)^{2} - 1 \\approx 4.269", explanation: "\\(f(x_{1})\\) is now extremely small — the previous step landed almost exactly on the root." }, { stepNumber: 2, description: "Apply the iteration.", workingLatex: "x_{2} = 1.32531 - \\frac{0.00016}{4.269} \\approx 1.3247", explanation: "The correction is in the fourth decimal place, confirming rapid convergence." }, { stepNumber: 3, description: "State the root to 3 d.p.", workingLatex: "x_{1} \\approx 1.3253,\\ x_{2} \\approx 1.3247 \\Rightarrow \\text{root} \\approx 1.325", explanation: "Both estimates round to \\(1.325\\) to 3 d.p., so we can quote the root to that accuracy with confidence." } ], finalAnswer: "Root \\(\\approx 1.325\\) to 3 d.p." } },
  { id: "y2nm4-011", topicRef: "y2nm4", topicTitle: "Newton-Raphson 11", difficulty: "Foundation", answerType: "expression", questionText: "Write the Newton-Raphson iteration for \\(f(x) = x^{3} - 5\\) and apply it once from \\(x_{0} = 2\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["derivation", "calculation"], workedSolution: { steps: [ { stepNumber: 1, description: "Form the iteration.", workingLatex: "f'(x) = 3x^{2} \\;\\Rightarrow\\; x_{n+1} = x_{n} - \\frac{x_{n}^{3} - 5}{3 x_{n}^{2}}", explanation: "Differentiate \\(f\\), then substitute \\(f\\) and \\(f'\\) into the general formula to get the iteration specific to this equation." }, { stepNumber: 2, description: "Evaluate the pieces at \\(x_{0} = 2\\).", workingLatex: "x_{0}^{3} - 5 = 8 - 5 = 3, \\quad 3 x_{0}^{2} = 3(4) = 12", explanation: "Compute the numerator \\(f(2)\\) and denominator \\(f'(2)\\) separately to keep the arithmetic clean." }, { stepNumber: 3, description: "Apply the iteration.", workingLatex: "x_{1} = 2 - \\frac{3}{12} = 2 - 0.25 = 1.75", explanation: "The correction is exactly \\(\\frac{1}{4}\\), giving a clean value \\(x_{1} = 1.75\\)." } ], finalAnswer: "\\(x_{1} = 1.75\\)." } },
  { id: "y2nm4-012", topicRef: "y2nm4", topicTitle: "Newton-Raphson 12", difficulty: "Foundation", answerType: "expression", questionText: "Show that the Newton-Raphson iteration for \\(f(x) = x^{n} - k\\) is \\(x_{n+1} = \\frac{(n-1)x_{n}^{n} + k}{n \\cdot x_{n}^{n-1}}\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["derivation"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate the general power.", workingLatex: "f(x) = x^{n} - k, \\quad f'(x) = n\\,x^{n-1}", explanation: "Treat \\(n\\) as a fixed positive integer and apply the power rule once." }, { stepNumber: 2, description: "Substitute into the formula.", workingLatex: "x_{n+1} = x_{n} - \\frac{x_{n}^{n} - k}{n\\,x_{n}^{n-1}}", explanation: "Here the iteration index and the power are both written \\(n\\); read \\(x_{n}\\) as the current estimate and \\(x^{n}\\) as the power." }, { stepNumber: 3, description: "Combine over a common denominator.", workingLatex: "x_{n+1} = \\frac{n\\,x_{n}^{n} - \\left(x_{n}^{n} - k\\right)}{n\\,x_{n}^{n-1}}", explanation: "Write \\(x_{n} = \\frac{n\\,x_{n}^{n}}{n\\,x_{n}^{n-1}}\\) and subtract the fraction." }, { stepNumber: 4, description: "Collect the numerator.", workingLatex: "x_{n+1} = \\frac{(n-1)x_{n}^{n} + k}{n\\,x_{n}^{n-1}}", explanation: "Since \\(n\\,x_{n}^{n} - x_{n}^{n} = (n-1)x_{n}^{n}\\), the result follows. This generalises the square-root iteration of Q7." } ], finalAnswer: "Shown: \\(x_{n+1} = \\displaystyle\\frac{(n-1)x_{n}^{n} + k}{n\\,x_{n}^{n-1}}\\)." } },
  { id: "y2nm4-013", topicRef: "y2nm4", topicTitle: "Newton-Raphson 13", difficulty: "Foundation", answerType: "expression", questionText: "Use Newton-Raphson on \\(f(x) = x^{2} - 3x - 2\\) with \\(x_{0} = 4\\). Compute \\(x_{1}\\) to 4 decimal places.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["calculation"], workedSolution: { steps: [ { stepNumber: 1, description: "Evaluate \\(f(x_{0})\\).", workingLatex: "f(4) = 16 - 12 - 2 = 2", explanation: "Substitute \\(x_{0} = 4\\) into \\(f\\); the positive value means the start point sits above the axis." }, { stepNumber: 2, description: "Differentiate and evaluate \\(f'(x_{0})\\).", workingLatex: "f'(x) = 2x - 3, \\quad f'(4) = 8 - 3 = 5", explanation: "The linear derivative is easy to evaluate; the gradient \\(5\\) sets the tangent's slope." }, { stepNumber: 3, description: "Apply the iteration.", workingLatex: "x_{1} = 4 - \\frac{2}{5} = 4 - 0.4 = 3.6000", explanation: "The correction \\(0.4\\) pulls the estimate toward the larger root of the quadratic." } ], finalAnswer: "\\(x_{1} = 3.6000\\)." } },
  { id: "y2nm4-014", topicRef: "y2nm4", topicTitle: "Newton-Raphson 14", difficulty: "Foundation", answerType: "expression", questionText: "Continuing Q13, compute \\(x_{2}\\) and \\(x_{3}\\) to 4 decimal places and state the positive root of \\(x^{2} - 3x - 2 = 0\\) to 3 decimal places.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["calculation"], workedSolution: { steps: [ { stepNumber: 1, description: "Evaluate \\(f\\) and \\(f'\\) at \\(x_{1}\\).", workingLatex: "f(3.6) = 12.96 - 10.8 - 2 = 0.16, \\quad f'(3.6) = 2(3.6) - 3 = 4.2", explanation: "\\(f\\) has dropped from \\(2\\) to \\(0.16\\); the estimate is already close to the root." }, { stepNumber: 2, description: "Compute \\(x_{2}\\).", workingLatex: "x_{2} = 3.6 - \\frac{0.16}{4.2} \\approx 3.5619", explanation: "A small correction of about \\(0.038\\) refines the estimate." }, { stepNumber: 3, description: "Compute \\(x_{3}\\).", workingLatex: "x_{3} = 3.56190 - \\frac{f(3.56190)}{f'(3.56190)} \\approx 3.5616", explanation: "\\(x_{3}\\) barely moves, confirming convergence." }, { stepNumber: 4, description: "State the root and check.", workingLatex: "\\frac{3 + \\sqrt{17}}{2} \\approx 3.5616 \\Rightarrow \\text{root} \\approx 3.562", explanation: "The quadratic formula gives the exact root \\(\\frac{3 + \\sqrt{17}}{2}\\), which agrees to 3 d.p." } ], finalAnswer: "\\(x_{2} \\approx 3.5619,\\ x_{3} \\approx 3.5616\\); root \\(\\approx 3.562\\) to 3 d.p." } },
  { id: "y2nm4-015", topicRef: "y2nm4", topicTitle: "Newton-Raphson 15", difficulty: "Foundation", answerType: "expression", questionText: "The Newton-Raphson method can fail if \\(f'(x_{n}) = 0\\). Explain why.", marks: 2, examStyle: false, yearCreated: 2026, tags: ["failure"], workedSolution: { steps: [ { stepNumber: 1, description: "Look at the denominator.", workingLatex: "x_{n+1} = x_{n} - \\frac{f(x_{n})}{f'(x_{n})}", explanation: "The formula divides by \\(f'(x_{n})\\). If that gradient is zero, the division is undefined and \\(x_{n+1}\\) cannot be computed." }, { stepNumber: 2, description: "Interpret geometrically.", workingLatex: "f'(x_{n}) = 0 \\;\\Rightarrow\\; \\text{tangent is horizontal}", explanation: "A horizontal tangent runs parallel to the x-axis, so it never crosses it — there is no next estimate to read off." } ], finalAnswer: "Dividing by \\(f'(x_{n}) = 0\\) is undefined; the tangent is horizontal and never meets the x-axis." } },
  { id: "y2nm4-016", topicRef: "y2nm4", topicTitle: "Newton-Raphson 16", difficulty: "Foundation", answerType: "expression", questionText: "For \\(f(x) = x^{2} - 4\\) with \\(x_{0} = 0\\), explain what goes wrong.", marks: 2, examStyle: false, yearCreated: 2026, tags: ["failure"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate and evaluate at \\(x_{0}\\).", workingLatex: "f'(x) = 2x, \\quad f'(0) = 0", explanation: "The derivative is zero exactly at the start point \\(x_{0} = 0\\), which is the vertex of the parabola." }, { stepNumber: 2, description: "Apply the failure condition.", workingLatex: "x_{1} = 0 - \\frac{f(0)}{0} \\;\\text{(undefined)}", explanation: "With \\(f'(x_{0}) = 0\\) the very first iteration divides by zero, so the method cannot even start." } ], finalAnswer: "\\(f'(x_{0}) = 0\\); the first iteration divides by zero and is undefined." } },
  { id: "y2nm4-017", topicRef: "y2nm4", topicTitle: "Newton-Raphson 17", difficulty: "Foundation", answerType: "expression", questionText: "Explain why starting Newton-Raphson for \\(f(x) = x^{3} - 3x + 1\\) at a turning point (\\(x = 1\\) or \\(x = -1\\)) fails.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["failure"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate and factorise.", workingLatex: "f'(x) = 3x^{2} - 3 = 3(x - 1)(x + 1)", explanation: "Setting \\(f'(x) = 0\\) locates the turning points. Factorising shows they sit at \\(x = \\pm 1\\)." }, { stepNumber: 2, description: "Evaluate the derivative there.", workingLatex: "f'(1) = 0, \\quad f'(-1) = 0", explanation: "Both turning points give a zero gradient." }, { stepNumber: 3, description: "Conclude.", workingLatex: "x_{1} = x_{0} - \\frac{f(x_{0})}{0} \\;\\text{(undefined)}", explanation: "A zero denominator makes the iteration undefined: the tangent at a turning point is horizontal and never reaches the x-axis." } ], finalAnswer: "The derivative is zero at \\(x = \\pm 1\\); the horizontal tangent gives a division by zero." } },
  { id: "y2nm4-018", topicRef: "y2nm4", topicTitle: "Newton-Raphson 18", difficulty: "Foundation", answerType: "expression", questionText: "Explain why Newton-Raphson may overshoot and diverge if \\(x_{0}\\) is far from the root.", marks: 2, examStyle: false, yearCreated: 2026, tags: ["failure"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the method is a local approximation.", workingLatex: "f(x) \\approx f(x_{n}) + f'(x_{n})(x - x_{n})", explanation: "Each step replaces the curve by its tangent, which is only an accurate model of \\(f\\) close to \\(x_{n}\\)." }, { stepNumber: 2, description: "Explain the consequence far from the root.", workingLatex: "", explanation: "Far from the root the tangent is a poor match for the curve, so its x-intercept can land even further away or in a region where the gradient sends later iterates off to infinity, and the sequence diverges." } ], finalAnswer: "Far starting values break the tangent-line approximation, so the next iterate can overshoot and the sequence diverges." } },
  { id: "y2nm4-019", topicRef: "y2nm4", topicTitle: "Newton-Raphson 19", difficulty: "Standard", answerType: "expression", questionText: "Apply Newton-Raphson to \\(f(x) = \\cos x - x\\) with \\(x_{0} = 0.5\\) (radians). Find \\(x_{1}\\) and \\(x_{2}\\) to 5 decimal places.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["calculation", "trigonometric"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate \\(f\\).", workingLatex: "f(x) = \\cos x - x, \\quad f'(x) = -\\sin x - 1", explanation: "Differentiate term by term: \\(\\frac{d}{dx}\\cos x = -\\sin x\\) and \\(\\frac{d}{dx}(-x) = -1\\). Keep the calculator in radians." }, { stepNumber: 2, description: "Evaluate at \\(x_{0} = 0.5\\).", workingLatex: "f(0.5) \\approx 0.37758, \\quad f'(0.5) \\approx -1.47943", explanation: "Substitute \\(0.5\\,\\text{rad}\\). The gradient is negative because the curve is falling here." }, { stepNumber: 3, description: "Compute \\(x_{1}\\).", workingLatex: "x_{1} = 0.5 - \\frac{0.37758}{-1.47943} \\approx 0.75522", explanation: "Subtracting a negative correction moves the estimate to the right, toward the root." }, { stepNumber: 4, description: "Compute \\(x_{2}\\).", workingLatex: "x_{2} = 0.75522 - \\frac{f(0.75522)}{f'(0.75522)} \\approx 0.73914", explanation: "Feeding \\(x_{1}\\) back in gives a much smaller correction — convergence toward \\(0.739\\) is well underway." } ], finalAnswer: "\\(x_{1} \\approx 0.75522,\\ x_{2} \\approx 0.73914\\)." } },
  { id: "y2nm4-020", topicRef: "y2nm4", topicTitle: "Newton-Raphson 20", difficulty: "Standard", answerType: "expression", questionText: "Apply Newton-Raphson to \\(f(x) = e^{x} - 3x\\) with \\(x_{0} = 1\\). Find \\(x_{1}\\) to 4 decimal places.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["calculation", "exponential"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate \\(f\\).", workingLatex: "f(x) = e^{x} - 3x, \\quad f'(x) = e^{x} - 3", explanation: "The derivative of \\(e^{x}\\) is itself; the derivative of \\(-3x\\) is \\(-3\\)." }, { stepNumber: 2, description: "Evaluate at \\(x_{0} = 1\\).", workingLatex: "f(1) = e - 3 \\approx -0.2817, \\quad f'(1) = e - 3 \\approx -0.2817", explanation: "By coincidence \\(f(1)\\) and \\(f'(1)\\) are equal here, since both reduce to \\(e - 3\\)." }, { stepNumber: 3, description: "Apply the iteration.", workingLatex: "x_{1} = 1 - \\frac{-0.2817}{-0.2817} = 1 - 1 = 0", explanation: "The equal numerator and denominator make the correction exactly \\(1\\), throwing the estimate to \\(0\\)." }, { stepNumber: 4, description: "Comment.", workingLatex: "", explanation: "Landing on \\(x_{1} = 0\\) shows \\(x_{0} = 1\\) was a poor start: it sat near the turning point of \\(f\\) where \\(f'\\) is small, so the tangent was shallow and overshot badly." } ], finalAnswer: "\\(x_{1} = 0\\) — a poor choice of \\(x_{0}\\) (shallow gradient causes a large jump)." } },
  { id: "y2nm4-021", topicRef: "y2nm4", topicTitle: "Newton-Raphson 21", difficulty: "Standard", answerType: "expression", questionText: "Based on Q20, suggest a better starting value and compute \\(x_{1}\\) to 4 decimal places. (There is a root between 0 and 1.)", marks: 4, examStyle: true, yearCreated: 2026, tags: ["calculation"], workedSolution: { steps: [ { stepNumber: 1, description: "Choose a start nearer the root.", workingLatex: "x_{0} = 0.5", explanation: "The hint locates a root in \\((0, 1)\\), so \\(0.5\\) is a sensible midpoint that avoids the shallow-gradient region near \\(x = 1\\)." }, { stepNumber: 2, description: "Evaluate \\(f\\) and \\(f'\\) at \\(0.5\\).", workingLatex: "f(0.5) = e^{0.5} - 1.5 \\approx 0.14872, \\quad f'(0.5) = e^{0.5} - 3 \\approx -1.35128", explanation: "The gradient is now well away from zero, so the tangent is steep and the step will be well-behaved." }, { stepNumber: 3, description: "Apply the iteration.", workingLatex: "x_{1} = 0.5 - \\frac{0.14872}{-1.35128} \\approx 0.6101", explanation: "A controlled correction of about \\(0.11\\) — no overshoot — moving toward the root near \\(0.619\\)." } ], finalAnswer: "Taking \\(x_{0} = 0.5\\) gives \\(x_{1} \\approx 0.6101\\) (converging to \\(\\approx 0.6191\\))." } },
  { id: "y2nm4-022", topicRef: "y2nm4", topicTitle: "Newton-Raphson 22", difficulty: "Standard", answerType: "expression", questionText: "Use Newton-Raphson on \\(f(x) = x - \\cos x\\) from \\(x_{0} = 0.7\\) (radians). Find \\(x_{1}\\) and \\(x_{2}\\) to 5 decimal places.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["calculation", "trigonometric"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate \\(f\\).", workingLatex: "f(x) = x - \\cos x, \\quad f'(x) = 1 + \\sin x", explanation: "The derivative of \\(-\\cos x\\) is \\(+\\sin x\\), so \\(f'(x) = 1 + \\sin x\\)." }, { stepNumber: 2, description: "Evaluate at \\(x_{0} = 0.7\\).", workingLatex: "f(0.7) = 0.7 - \\cos 0.7 \\approx 0.7 - 0.76484 = -0.06484, \\quad f'(0.7) = 1 + \\sin 0.7 \\approx 1.64422", explanation: "Note \\(\\cos 0.7 \\approx 0.76484 > 0.7\\), so \\(f(0.7)\\) is negative: the root lies just to the right of \\(0.7\\)." }, { stepNumber: 3, description: "Compute \\(x_{1}\\).", workingLatex: "x_{1} = 0.7 - \\frac{-0.06484}{1.64422} = 0.7 + 0.03944 \\approx 0.73944", explanation: "Subtracting the negative correction moves the estimate right, consistent with the sign of \\(f\\)." }, { stepNumber: 4, description: "Compute \\(x_{2}\\).", workingLatex: "x_{2} = 0.73944 - \\frac{f(0.73944)}{f'(0.73944)} \\approx 0.73944 - \\frac{0.00059}{1.67387} \\approx 0.73909", explanation: "The correction has collapsed to the fifth decimal place: the sequence is closing on the root \\(\\approx 0.73909\\)." } ], finalAnswer: "\\(x_{1} \\approx 0.73944,\\ x_{2} \\approx 0.73909\\)." } },
  { id: "y2nm4-023", topicRef: "y2nm4", topicTitle: "Newton-Raphson 23", difficulty: "Standard", answerType: "expression", questionText: "Use Newton-Raphson on \\(f(x) = \\ln x - 1\\) with \\(x_{0} = 2\\). Find \\(x_{1}\\) and \\(x_{2}\\) to 4 decimal places. (The root is \\(e\\).)", marks: 4, examStyle: true, yearCreated: 2026, tags: ["calculation", "log"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate \\(f\\).", workingLatex: "f(x) = \\ln x - 1, \\quad f'(x) = \\frac{1}{x}", explanation: "The derivative of \\(\\ln x\\) is \\(\\frac{1}{x}\\); the constant differentiates to zero." }, { stepNumber: 2, description: "Simplify the iteration.", workingLatex: "x_{n+1} = x_{n} - \\frac{\\ln x_{n} - 1}{1/x_{n}} = x_{n} - x_{n}\\left(\\ln x_{n} - 1\\right)", explanation: "Dividing by \\(\\frac{1}{x_{n}}\\) is the same as multiplying by \\(x_{n}\\), which tidies the formula before substituting numbers." }, { stepNumber: 3, description: "Compute \\(x_{1}\\).", workingLatex: "x_{1} = 2 - 2(\\ln 2 - 1) = 2 - 2(-0.30685) \\approx 2.6137", explanation: "Since \\(\\ln 2 < 1\\), the bracket is negative and the estimate increases toward \\(e\\)." }, { stepNumber: 4, description: "Compute \\(x_{2}\\).", workingLatex: "x_{2} = 2.6137 - 2.6137(\\ln 2.6137 - 1) \\approx 2.6137 - 2.6137(-0.03923) \\approx 2.7162", explanation: "\\(x_{2} \\approx 2.7162\\) is close to \\(e \\approx 2.7183\\); a further step would essentially reach it." } ], finalAnswer: "\\(x_{1} \\approx 2.6137,\\ x_{2} \\approx 2.7162\\); compare \\(e \\approx 2.7183\\)." } },
  { id: "y2nm4-024", topicRef: "y2nm4", topicTitle: "Newton-Raphson 24", difficulty: "Standard", answerType: "expression", questionText: "The equation \\(x e^{x} = 1\\) has a root near \\(x = 0.5\\). Apply Newton-Raphson once to find \\(x_{1}\\) to 5 decimal places.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["calculation"], workedSolution: { steps: [ { stepNumber: 1, description: "Rearrange to \\(f(x) = 0\\) form.", workingLatex: "x e^{x} = 1 \\;\\Rightarrow\\; f(x) = x e^{x} - 1", explanation: "Newton-Raphson needs a function equal to zero at the root, so move everything to one side." }, { stepNumber: 2, description: "Differentiate using the product rule.", workingLatex: "f'(x) = (1)e^{x} + x e^{x} = (x + 1)e^{x}", explanation: "Differentiate \\(x e^{x}\\) as a product: \\(u = x,\\ v = e^{x}\\), so \\(u'v + uv' = e^{x} + x e^{x}\\), then factor out \\(e^{x}\\)." }, { stepNumber: 3, description: "Evaluate at \\(x_{0} = 0.5\\).", workingLatex: "f(0.5) \\approx -0.17564, \\quad f'(0.5) \\approx 2.47308", explanation: "\\(f(0.5)\\) is negative, so the root lies to the right of \\(0.5\\)." }, { stepNumber: 4, description: "Apply the iteration.", workingLatex: "x_{1} = 0.5 - \\frac{-0.17564}{2.47308} = 0.5 + 0.07102 \\approx 0.57102", explanation: "The negative \\(f\\) and positive \\(f'\\) push the estimate right, as expected." } ], finalAnswer: "\\(x_{1} \\approx 0.57102\\)." } },
  { id: "y2nm4-025", topicRef: "y2nm4", topicTitle: "Newton-Raphson 25", difficulty: "Standard", answerType: "expression", questionText: "Use Newton-Raphson on \\(f(x) = x^{3} - 2x - 5\\) with \\(x_{0} = 2\\). Find \\(x_{1},\\ x_{2}\\) and \\(x_{3}\\) to 5 decimal places.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["calculation"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate \\(f\\).", workingLatex: "f(x) = x^{3} - 2x - 5, \\quad f'(x) = 3x^{2} - 2", explanation: "This is the cubic Newton himself used. Differentiate term by term." }, { stepNumber: 2, description: "Evaluate at \\(x_{0} = 2\\) and find \\(x_{1}\\).", workingLatex: "f(2) = 8 - 4 - 5 = -1, \\quad f'(2) = 10 \\;\\Rightarrow\\; x_{1} = 2 - \\frac{-1}{10} = 2.10000", explanation: "A small negative \\(f\\) over a steep gradient gives a modest step to the right." }, { stepNumber: 3, description: "Compute \\(x_{2}\\).", workingLatex: "x_{2} = 2.1 - \\frac{f(2.1)}{f'(2.1)} = 2.1 - \\frac{0.061}{11.23} \\approx 2.09457", explanation: "Feeding \\(x_{1}\\) back in gives a much smaller correction — the hallmark of fast convergence." }, { stepNumber: 4, description: "Compute \\(x_{3}\\).", workingLatex: "x_{3} = 2.09457 - \\frac{f(2.09457)}{f'(2.09457)} \\approx 2.09455", explanation: "\\(x_{3}\\) differs from \\(x_{2}\\) only in the fifth decimal, so the root is \\(\\approx 2.09455\\)." } ], finalAnswer: "\\(x_{1} = 2.1,\\ x_{2} \\approx 2.09457,\\ x_{3} \\approx 2.09455\\)." } },
  { id: "y2nm4-026", topicRef: "y2nm4", topicTitle: "Newton-Raphson 26", difficulty: "Standard", answerType: "expression", questionText: "Apply Newton-Raphson to \\(f(x) = \\sin x - \\frac{x}{2}\\) with \\(x_{0} = 2\\) (radians). Give \\(x_{1}\\) to 5 decimal places.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["calculation", "trigonometric"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate \\(f\\).", workingLatex: "f(x) = \\sin x - \\frac{x}{2}, \\quad f'(x) = \\cos x - \\frac{1}{2}", explanation: "Differentiate \\(\\sin x\\) to \\(\\cos x\\) and \\(\\frac{x}{2}\\) to \\(\\frac{1}{2}\\). Stay in radians." }, { stepNumber: 2, description: "Evaluate at \\(x_{0} = 2\\).", workingLatex: "f(2) = \\sin 2 - 1 \\approx -0.09070, \\quad f'(2) = \\cos 2 - 0.5 \\approx -0.91615", explanation: "Both \\(f\\) and \\(f'\\) are negative here, so the correction will be negative and the estimate decreases." }, { stepNumber: 3, description: "Apply the iteration.", workingLatex: "x_{1} = 2 - \\frac{-0.09070}{-0.91615} = 2 - 0.09900 \\approx 1.90100", explanation: "A negative over a negative is positive, so we subtract a positive correction and move left toward the root." } ], finalAnswer: "\\(x_{1} \\approx 1.90100\\)." } },
  { id: "y2nm4-027", topicRef: "y2nm4", topicTitle: "Newton-Raphson 27", difficulty: "Standard", answerType: "expression", questionText: "Explain why \\(x_{n+1} = g(x_{n})\\) with \\(g(x) = x - f(x)/f'(x)\\) satisfies \\(g'(\\alpha) = 0\\) at any simple root \\(\\alpha\\) of \\(f\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["convergence"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate \\(g\\) using the quotient rule.", workingLatex: "g'(x) = 1 - \\frac{f'(x)\\,f'(x) - f(x)\\,f''(x)}{\\left(f'(x)\\right)^{2}}", explanation: "Treat \\(g(x) = x - \\frac{f}{f'}\\). Differentiating the fraction needs the quotient rule with numerator \\(f\\) and denominator \\(f'\\)." }, { stepNumber: 2, description: "Simplify the expression.", workingLatex: "g'(x) = 1 - \\frac{\\left(f'(x)\\right)^{2} - f(x)f''(x)}{\\left(f'(x)\\right)^{2}} = \\frac{f(x)\\,f''(x)}{\\left(f'(x)\\right)^{2}}", explanation: "The \\(\\left(f'\\right)^{2}\\) terms cancel against the leading \\(1\\), leaving a single clean fraction." }, { stepNumber: 3, description: "Evaluate at a simple root.", workingLatex: "f(\\alpha) = 0,\\ f'(\\alpha) \\neq 0 \\;\\Rightarrow\\; g'(\\alpha) = \\frac{0 \\cdot f''(\\alpha)}{\\left(f'(\\alpha)\\right)^{2}} = 0", explanation: "At a simple root \\(f(\\alpha) = 0\\) but \\(f'(\\alpha) \\neq 0\\), so the numerator vanishes while the denominator does not. A zero derivative of the iteration map is what produces quadratic convergence." } ], finalAnswer: "\\(g'(\\alpha) = \\displaystyle\\frac{f(\\alpha)f''(\\alpha)}{\\left(f'(\\alpha)\\right)^{2}} = 0\\), which gives quadratic convergence." } },
  { id: "y2nm4-028", topicRef: "y2nm4", topicTitle: "Newton-Raphson 28", difficulty: "Standard", answerType: "expression", questionText: "State what is meant by quadratic convergence.", marks: 2, examStyle: false, yearCreated: 2026, tags: ["theory"], workedSolution: { steps: [ { stepNumber: 1, description: "Write the error inequality.", workingLatex: "\\left|x_{n+1} - \\alpha\\right| \\leq C\\left|x_{n} - \\alpha\\right|^{2}", explanation: "Let \\(\\alpha\\) be the root. The error \\(\\left|x_{n+1} - \\alpha\\right|\\) at one step is bounded by a constant \\(C\\) times the square of the previous error, for \\(x_{n}\\) near the root." }, { stepNumber: 2, description: "Interpret it.", workingLatex: "", explanation: "Squaring the error means the number of correct decimal places roughly doubles each step — which is why Newton-Raphson converges so quickly once it is close." } ], finalAnswer: "The error at each step is proportional to the square of the previous error: \\(\\left|x_{n+1} - \\alpha\\right| \\leq C\\left|x_{n} - \\alpha\\right|^{2}\\)." } },
  { id: "y2nm4-029", topicRef: "y2nm4", topicTitle: "Newton-Raphson 29", difficulty: "Standard", answerType: "expression", questionText: "The Newton-Raphson iteration for \\(f(x) = x^{4} - 3\\) is \\(x_{n+1} = \\frac{3 x_{n}^{4} + 3}{4 x_{n}^{3}}\\). Apply it with \\(x_{0} = 1.5\\). Compute \\(x_{1}\\) to 5 decimal places.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["calculation"], workedSolution: { steps: [ { stepNumber: 1, description: "Evaluate the numerator at \\(x_{0} = 1.5\\).", workingLatex: "3 x_{0}^{4} + 3 = 3(1.5)^{4} + 3 = 3(5.0625) + 3 = 18.1875", explanation: "Work out the top of the fraction first; \\((1.5)^{4} = 5.0625\\)." }, { stepNumber: 2, description: "Evaluate the denominator.", workingLatex: "4 x_{0}^{3} = 4(1.5)^{3} = 4(3.375) = 13.5", explanation: "Then the bottom: \\((1.5)^{3} = 3.375\\)." }, { stepNumber: 3, description: "Divide to get \\(x_{1}\\).", workingLatex: "x_{1} = \\frac{18.1875}{13.5} \\approx 1.34722", explanation: "The estimate drops sharply from \\(1.5\\) toward \\(\\sqrt[4]{3}\\)." } ], finalAnswer: "\\(x_{1} \\approx 1.34722\\)." } },
  { id: "y2nm4-030", topicRef: "y2nm4", topicTitle: "Newton-Raphson 30", difficulty: "Standard", answerType: "expression", questionText: "Continuing Q29, compute \\(x_{2}\\) to 5 decimal places. Compare with \\(\\sqrt[4]{3}\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["calculation"], workedSolution: { steps: [ { stepNumber: 1, description: "Substitute \\(x_{1}\\) into the iteration.", workingLatex: "x_{2} = \\frac{3(1.34722)^{4} + 3}{4(1.34722)^{3}}", explanation: "Reuse the simplified iteration with the unrounded \\(x_{1} \\approx 1.34722\\)." }, { stepNumber: 2, description: "Evaluate and simplify.", workingLatex: "x_{2} = \\frac{12.88268}{9.78087} \\approx 1.31714", explanation: "The estimate continues to fall toward the true root, though it is still slightly above it after only two steps." }, { stepNumber: 3, description: "Compare with \\(\\sqrt[4]{3}\\).", workingLatex: "\\sqrt[4]{3} \\approx 1.31607", explanation: "\\(x_{2} \\approx 1.31714\\) is within about \\(0.001\\) of \\(\\sqrt[4]{3}\\); a third step would tighten this considerably." } ], finalAnswer: "\\(x_{2} \\approx 1.31714\\); compare \\(\\sqrt[4]{3} \\approx 1.31607\\)." } },
  { id: "y2nm4-031", topicRef: "y2nm4", topicTitle: "Newton-Raphson 31", difficulty: "Standard", answerType: "expression", questionText: "Use Newton-Raphson on \\(f(x) = \\tan x - 1\\) with \\(x_{0} = 0.8\\) (radians). Find \\(x_{1}\\) to 5 decimal places.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["calculation", "trigonometric"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate \\(f\\).", workingLatex: "f(x) = \\tan x - 1, \\quad f'(x) = \\sec^{2} x", explanation: "The derivative of \\(\\tan x\\) is \\(\\sec^{2} x = \\frac{1}{\\cos^{2} x}\\)." }, { stepNumber: 2, description: "Evaluate at \\(x_{0} = 0.8\\).", workingLatex: "f(0.8) = \\tan 0.8 - 1 \\approx 0.02964, \\quad f'(0.8) = \\sec^{2} 0.8 \\approx 2.06016", explanation: "Compute \\(\\sec^{2} 0.8 = 1/\\cos^{2} 0.8 \\approx 2.06016\\). The root is just left of \\(0.8\\) since \\(f\\) is slightly positive." }, { stepNumber: 3, description: "Apply the iteration.", workingLatex: "x_{1} = 0.8 - \\frac{0.02964}{2.06016} = 0.8 - 0.01439 \\approx 0.78561", explanation: "The small positive correction moves the estimate left toward \\(\\frac{\\pi}{4} \\approx 0.78540\\), the exact root of \\(\\tan x = 1\\)." } ], finalAnswer: "\\(x_{1} \\approx 0.78561\\)." } },
  { id: "y2nm4-032", topicRef: "y2nm4", topicTitle: "Newton-Raphson 32", difficulty: "Standard", answerType: "expression", questionText: "Apply Newton-Raphson to \\(f(x) = x^{2} - 2\\sin x - 1\\) with \\(x_{0} = 2\\) (radians). Find \\(x_{1}\\) to 5 decimal places.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["calculation"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate \\(f\\).", workingLatex: "f(x) = x^{2} - 2\\sin x - 1, \\quad f'(x) = 2x - 2\\cos x", explanation: "Differentiate each term: \\(x^{2} \\to 2x\\), \\(-2\\sin x \\to -2\\cos x\\), constant \\(\\to 0\\)." }, { stepNumber: 2, description: "Evaluate at \\(x_{0} = 2\\).", workingLatex: "f(2) = 4 - 2\\sin 2 - 1 \\approx 1.18141, \\quad f'(2) = 4 - 2\\cos 2 \\approx 4.83229", explanation: "Keep the calculator in radians; \\(\\sin 2 \\approx 0.90930\\) and \\(\\cos 2 \\approx -0.41615\\)." }, { stepNumber: 3, description: "Apply the iteration.", workingLatex: "x_{1} = 2 - \\frac{1.18141}{4.83229} = 2 - 0.24448 \\approx 1.75552", explanation: "A positive \\(f\\) over a positive gradient gives a leftward step toward the root." } ], finalAnswer: "\\(x_{1} \\approx 1.75552\\)." } },
  { id: "y2nm4-033", topicRef: "y2nm4", topicTitle: "Newton-Raphson 33", difficulty: "Standard", answerType: "expression", questionText: "Apply Newton-Raphson to the equation \\(x^{5} - x - 1 = 0\\) from \\(x_{0} = 1\\). Compute \\(x_{1}\\) and \\(x_{2}\\) to 5 decimal places.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["calculation"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate \\(f\\).", workingLatex: "f(x) = x^{5} - x - 1, \\quad f'(x) = 5x^{4} - 1", explanation: "Power rule on \\(x^{5}\\) gives \\(5x^{4}\\); the \\(-x\\) gives \\(-1\\)." }, { stepNumber: 2, description: "Evaluate at \\(x_{0} = 1\\) and find \\(x_{1}\\).", workingLatex: "f(1) = 1 - 1 - 1 = -1, \\quad f'(1) = 4 \\;\\Rightarrow\\; x_{1} = 1 - \\frac{-1}{4} = 1.25000", explanation: "A negative \\(f\\) over a positive gradient steps the estimate to the right." }, { stepNumber: 3, description: "Compute \\(x_{2}\\).", workingLatex: "x_{2} = 1.25 - \\frac{(1.25)^{5} - 1.25 - 1}{5(1.25)^{4} - 1} = 1.25 - \\frac{0.80176}{11.20703} \\approx 1.17846", explanation: "The first step overshot a little, so the second step corrects back down toward the root near \\(1.1673\\)." } ], finalAnswer: "\\(x_{1} = 1.25,\\ x_{2} \\approx 1.17846\\)." } },
  { id: "y2nm4-034", topicRef: "y2nm4", topicTitle: "Newton-Raphson 34", difficulty: "Standard", answerType: "expression", questionText: "Use Newton-Raphson to find the positive root of \\(f(x) = 2^{x} - 3x\\). Use \\(x_{0} = 1\\) and compute \\(x_{1}\\) to 5 decimal places.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["calculation", "exponential"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate the exponential.", workingLatex: "f(x) = 2^{x} - 3x, \\quad f'(x) = 2^{x}\\ln 2 - 3", explanation: "Recall \\(\\frac{d}{dx}a^{x} = a^{x}\\ln a\\); here \\(a = 2\\), so the derivative of \\(2^{x}\\) is \\(2^{x}\\ln 2\\)." }, { stepNumber: 2, description: "Evaluate at \\(x_{0} = 1\\).", workingLatex: "f(1) = 2 - 3 = -1, \\quad f'(1) = 2\\ln 2 - 3 \\approx -1.61371", explanation: "Both are negative here, so the correction will be negative and the estimate decreases." }, { stepNumber: 3, description: "Apply the iteration.", workingLatex: "x_{1} = 1 - \\frac{-1}{-1.61371} = 1 - 0.61969 \\approx 0.38031", explanation: "Negative over negative is positive, so we subtract about \\(0.62\\) and move toward the smaller positive root." } ], finalAnswer: "\\(x_{1} \\approx 0.38031\\)." } },
  { id: "y2nm4-035", topicRef: "y2nm4", topicTitle: "Newton-Raphson 35", difficulty: "Standard", answerType: "expression", questionText: "Apply Newton-Raphson to \\(f(x) = x \\ln x - 1\\) starting from \\(x_{0} = 2\\). Find \\(x_{1}\\) to 5 decimal places.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["calculation", "log"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate using the product rule.", workingLatex: "f'(x) = (1)\\ln x + x\\cdot\\frac{1}{x} = \\ln x + 1", explanation: "Differentiate \\(x\\ln x\\) as a product: \\(\\frac{d}{dx}(x)\\cdot\\ln x + x\\cdot\\frac{d}{dx}(\\ln x) = \\ln x + 1\\)." }, { stepNumber: 2, description: "Evaluate at \\(x_{0} = 2\\).", workingLatex: "f(2) = 2\\ln 2 - 1 \\approx 0.38629, \\quad f'(2) = \\ln 2 + 1 \\approx 1.69315", explanation: "\\(f(2)\\) is positive, so the root lies to the left of \\(2\\)." }, { stepNumber: 3, description: "Apply the iteration.", workingLatex: "x_{1} = 2 - \\frac{0.38629}{1.69315} = 2 - 0.22815 \\approx 1.77185", explanation: "The estimate moves left toward the root near \\(1.763\\) of \\(x\\ln x = 1\\)." } ], finalAnswer: "\\(x_{1} \\approx 1.77185\\)." } },
  { id: "y2nm4-036", topicRef: "y2nm4", topicTitle: "Newton-Raphson 36", difficulty: "Standard", answerType: "expression", questionText: "For \\(f(x) = x^{3} - 3x + 1\\), apply Newton-Raphson with \\(x_{0} = 2\\). Compute \\(x_{1},\\ x_{2}\\) and state the root to 4 decimal places.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["calculation"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate \\(f\\).", workingLatex: "f(x) = x^{3} - 3x + 1, \\quad f'(x) = 3x^{2} - 3", explanation: "Differentiate term by term; note \\(f'(x) = 0\\) at \\(x = \\pm 1\\), so we should keep the iterates away from there." }, { stepNumber: 2, description: "Compute \\(x_{1}\\).", workingLatex: "f(2) = 8 - 6 + 1 = 3, \\quad f'(2) = 9 \\;\\Rightarrow\\; x_{1} = 2 - \\frac{3}{9} \\approx 1.66667", explanation: "A steep gradient keeps the first step well-controlled." }, { stepNumber: 3, description: "Compute \\(x_{2}\\).", workingLatex: "f(1.66667) \\approx 0.62963, \\quad f'(1.66667) \\approx 5.33333 \\;\\Rightarrow\\; x_{2} = 1.66667 - \\frac{0.62963}{5.33333} \\approx 1.54861", explanation: "The estimate keeps descending toward the root; the correction is shrinking each step." }, { stepNumber: 4, description: "Iterate once more and state the root.", workingLatex: "x_{3} = 1.54861 - \\frac{0.06804}{4.19459} \\approx 1.53239 \\;\\Rightarrow\\; \\text{root} \\approx 1.5321", explanation: "\\(x_{3}\\) is stable to 4 d.p. at \\(1.5324\\); one more step settles it to \\(1.5321\\)." } ], finalAnswer: "\\(x_{1} \\approx 1.66667,\\ x_{2} \\approx 1.54861\\); root \\(\\approx 1.5321\\)." } },
  { id: "y2nm4-037", topicRef: "y2nm4", topicTitle: "Newton-Raphson 37", difficulty: "Standard", answerType: "expression", questionText: "For \\(f(x) = x^{3} - 3x + 1\\), start Newton-Raphson at \\(x_{0} = 1\\). Explain what happens and why.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["failure"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate and evaluate at \\(x_{0}\\).", workingLatex: "f'(x) = 3x^{2} - 3, \\quad f'(1) = 3 - 3 = 0", explanation: "\\(x = 1\\) is a turning point of \\(f\\), where the gradient is zero." }, { stepNumber: 2, description: "Apply the failure condition.", workingLatex: "x_{1} = 1 - \\frac{f(1)}{0} \\;\\text{(undefined)}", explanation: "Dividing by \\(f'(1) = 0\\) is undefined, so the iteration cannot proceed: the tangent at the turning point is horizontal and never meets the x-axis." } ], finalAnswer: "\\(f'(x_{0}) = 0\\) at the turning point \\(x = 1\\), so the first step is undefined." } },
  { id: "y2nm4-038", topicRef: "y2nm4", topicTitle: "Newton-Raphson 38", difficulty: "Standard", answerType: "expression", questionText: "Use Newton-Raphson on \\(f(x) = \\cos x\\) with \\(x_{0} = 1.5\\) (radians). Find \\(x_{1}\\) to 5 decimal places. State the exact root.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["calculation", "trigonometric"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate \\(f\\).", workingLatex: "f(x) = \\cos x, \\quad f'(x) = -\\sin x", explanation: "The derivative of \\(\\cos x\\) is \\(-\\sin x\\)." }, { stepNumber: 2, description: "Evaluate at \\(x_{0} = 1.5\\).", workingLatex: "f(1.5) = \\cos 1.5 \\approx 0.07074, \\quad f'(1.5) = -\\sin 1.5 \\approx -0.99749", explanation: "\\(f\\) is small and positive, and the gradient is close to \\(-1\\)." }, { stepNumber: 3, description: "Apply the iteration.", workingLatex: "x_{1} = 1.5 - \\frac{0.07074}{-0.99749} = 1.5 + 0.07091 \\approx 1.57091", explanation: "The estimate moves right toward \\(\\frac{\\pi}{2}\\)." }, { stepNumber: 4, description: "State the exact root.", workingLatex: "\\cos x = 0 \\;\\Rightarrow\\; x = \\frac{\\pi}{2} \\approx 1.57080", explanation: "\\(x_{1} \\approx 1.57091\\) already matches \\(\\frac{\\pi}{2}\\) to 3 d.p." } ], finalAnswer: "\\(x_{1} \\approx 1.57091\\); exact root \\(\\frac{\\pi}{2}\\)." } },
  { id: "y2nm4-039", topicRef: "y2nm4", topicTitle: "Newton-Raphson 39", difficulty: "Standard", answerType: "expression", questionText: "Show that applying Newton-Raphson to \\(f(x) = 1/x - a\\) gives \\(x_{n+1} = x_{n}(2 - a x_{n})\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["derivation"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate \\(f\\).", workingLatex: "f(x) = \\frac{1}{x} - a = x^{-1} - a, \\quad f'(x) = -x^{-2} = -\\frac{1}{x^{2}}", explanation: "Write \\(\\frac{1}{x}\\) as \\(x^{-1}\\) so the power rule applies cleanly." }, { stepNumber: 2, description: "Substitute into the formula.", workingLatex: "x_{n+1} = x_{n} - \\frac{\\frac{1}{x_{n}} - a}{-\\frac{1}{x_{n}^{2}}}", explanation: "Put \\(f\\) and \\(f'\\) into the iteration. The compound fraction is the only awkward part — handle it next." }, { stepNumber: 3, description: "Simplify the compound fraction.", workingLatex: "x_{n+1} = x_{n} + x_{n}^{2}\\!\\left(\\frac{1}{x_{n}} - a\\right) = x_{n} + x_{n} - a x_{n}^{2}", explanation: "Dividing by \\(-\\frac{1}{x_{n}^{2}}\\) means multiplying by \\(-x_{n}^{2}\\); the two minus signs combine to a plus." }, { stepNumber: 4, description: "Factor out \\(x_{n}\\).", workingLatex: "x_{n+1} = 2x_{n} - a x_{n}^{2} = x_{n}(2 - a x_{n})", explanation: "This division-free iteration is how computers compute reciprocals \\(\\frac{1}{a}\\) without dividing." } ], finalAnswer: "Shown: \\(x_{n+1} = x_{n}(2 - a x_{n})\\)." } },
  { id: "y2nm4-040", topicRef: "y2nm4", topicTitle: "Newton-Raphson 40", difficulty: "Standard", answerType: "expression", questionText: "Use the iteration in Q39 with \\(a = 3\\) and \\(x_{0} = 0.3\\) to approximate \\(1/3\\). Compute \\(x_{1}\\) and \\(x_{2}\\) to 5 decimal places.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["calculation"], workedSolution: { steps: [ { stepNumber: 1, description: "Specialise the iteration to \\(a = 3\\).", workingLatex: "x_{n+1} = x_{n}(2 - 3 x_{n})", explanation: "Substitute \\(a = 3\\) into the division-free iteration from Q39." }, { stepNumber: 2, description: "Compute \\(x_{1}\\).", workingLatex: "x_{1} = 0.3\\,(2 - 3(0.3)) = 0.3(2 - 0.9) = 0.3(1.1) = 0.33000", explanation: "Starting close to \\(\\frac{1}{3}\\) means the first step already lands near it." }, { stepNumber: 3, description: "Compute \\(x_{2}\\).", workingLatex: "x_{2} = 0.33\\,(2 - 3(0.33)) = 0.33(2 - 0.99) = 0.33(1.01) = 0.33330", explanation: "\\(x_{2} = 0.33330\\) is already \\(\\frac{1}{3}\\) to 4 d.p.; convergence is quadratic." } ], finalAnswer: "\\(x_{1} = 0.33000,\\ x_{2} = 0.33330\\) (approaching \\(\\frac{1}{3}\\))." } },
  { id: "y2nm4-041", topicRef: "y2nm4", topicTitle: "Newton-Raphson 41", difficulty: "Standard", answerType: "expression", questionText: "Apply Newton-Raphson to \\(f(x) = x \\sin x - 1\\) starting from \\(x_{0} = 1\\) (radians). Find \\(x_{1}\\) to 5 decimal places.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["calculation"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate using the product rule.", workingLatex: "f'(x) = (1)\\sin x + x\\cos x = \\sin x + x\\cos x", explanation: "Differentiate \\(x\\sin x\\) as a product: derivative of \\(x\\) times \\(\\sin x\\), plus \\(x\\) times derivative of \\(\\sin x\\)." }, { stepNumber: 2, description: "Evaluate at \\(x_{0} = 1\\).", workingLatex: "f(1) = \\sin 1 - 1 \\approx -0.15853, \\quad f'(1) = \\sin 1 + \\cos 1 \\approx 1.38177", explanation: "\\(f(1)\\) is negative, so the root lies to the right of \\(1\\)." }, { stepNumber: 3, description: "Apply the iteration.", workingLatex: "x_{1} = 1 - \\frac{-0.15853}{1.38177} = 1 + 0.11473 \\approx 1.11473", explanation: "Subtracting a negative correction moves the estimate right toward the root near \\(1.114\\)." } ], finalAnswer: "\\(x_{1} \\approx 1.11473\\)." } },
  { id: "y2nm4-042", topicRef: "y2nm4", topicTitle: "Newton-Raphson 42", difficulty: "Standard", answerType: "expression", questionText: "A Newton-Raphson sketch shows the tangent at \\((x_{n}, f(x_{n}))\\) meeting the x-axis at \\(x_{n+1}\\). Given \\(f(x_{n}) = 2\\) and \\(f'(x_{n}) = 5\\), calculate \\(x_{n+1} - x_{n}\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["geometry"], workedSolution: { steps: [ { stepNumber: 1, description: "Rearrange the iteration for the step size.", workingLatex: "x_{n+1} - x_{n} = -\\frac{f(x_{n})}{f'(x_{n})}", explanation: "The Newton-Raphson formula already isolates the change in \\(x\\) as \\(-\\frac{f}{f'}\\)." }, { stepNumber: 2, description: "Substitute the given values.", workingLatex: "x_{n+1} - x_{n} = -\\frac{2}{5} = -0.4", explanation: "The negative sign shows the tangent carries the estimate to the left by \\(0.4\\)." } ], finalAnswer: "\\(x_{n+1} - x_{n} = -0.4\\)." } },
  { id: "y2nm4-043", topicRef: "y2nm4", topicTitle: "Newton-Raphson 43", difficulty: "Standard", answerType: "expression", questionText: "Starting from \\(x_{0} = 0\\), apply Newton-Raphson to \\(f(x) = x^{3} + 2x - 1\\). Find \\(x_{1}\\) to 5 decimal places.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["calculation"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate and check \\(f'(x_{0}) \\neq 0\\).", workingLatex: "f'(x) = 3x^{2} + 2, \\quad f'(0) = 2", explanation: "Here \\(f'(0) = 2 \\neq 0\\), so starting at \\(x_{0} = 0\\) is safe — the iteration is defined." }, { stepNumber: 2, description: "Evaluate \\(f\\) at \\(x_{0}\\).", workingLatex: "f(0) = 0 + 0 - 1 = -1", explanation: "A negative value at the origin tells us the root lies to the right." }, { stepNumber: 3, description: "Apply the iteration.", workingLatex: "x_{1} = 0 - \\frac{-1}{2} = 0.50000", explanation: "The first step jumps to \\(0.5\\), close to the real root of the cubic." } ], finalAnswer: "\\(x_{1} = 0.50000\\)." } },
  { id: "y2nm4-044", topicRef: "y2nm4", topicTitle: "Newton-Raphson 44", difficulty: "Standard", answerType: "expression", questionText: "Continuing Q43, compute \\(x_{2}\\) and \\(x_{3}\\) to 5 decimal places.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["calculation"], workedSolution: { steps: [ { stepNumber: 1, description: "Evaluate \\(f\\) and \\(f'\\) at \\(x_{1} = 0.5\\).", workingLatex: "f(0.5) = 0.125 + 1 - 1 = 0.125, \\quad f'(0.5) = 3(0.25) + 2 = 2.75", explanation: "\\(f(0.5)\\) is small and positive, so the root is just left of \\(0.5\\)." }, { stepNumber: 2, description: "Compute \\(x_{2}\\).", workingLatex: "x_{2} = 0.5 - \\frac{0.125}{2.75} \\approx 0.45455", explanation: "A modest correction pulls the estimate left." }, { stepNumber: 3, description: "Compute \\(x_{3}\\).", workingLatex: "x_{3} = 0.45455 - \\frac{f(0.45455)}{f'(0.45455)} \\approx 0.45340", explanation: "The change is now in the third decimal place, confirming rapid convergence toward \\(0.4534\\)." } ], finalAnswer: "\\(x_{2} \\approx 0.45455,\\ x_{3} \\approx 0.45340\\)." } },
  { id: "y2nm4-045", topicRef: "y2nm4", topicTitle: "Newton-Raphson 45", difficulty: "Standard", answerType: "expression", questionText: "Use Newton-Raphson to solve \\(x = \\ln(3 - x)\\) from \\(x_{0} = 1\\). Find \\(x_{1}\\) to 5 decimal places. (Rewrite as \\(f(x) = x - \\ln(3 - x)\\).)", marks: 4, examStyle: true, yearCreated: 2026, tags: ["calculation", "log"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate, using the chain rule on the log.", workingLatex: "f(x) = x - \\ln(3 - x), \\quad f'(x) = 1 - \\frac{-1}{3 - x} = 1 + \\frac{1}{3 - x}", explanation: "The derivative of \\(\\ln(3 - x)\\) is \\(\\frac{1}{3 - x}\\) times the inner derivative \\(-1\\); the two minus signs give \\(+\\frac{1}{3 - x}\\)." }, { stepNumber: 2, description: "Evaluate at \\(x_{0} = 1\\).", workingLatex: "f(1) = 1 - \\ln 2 \\approx 0.30685, \\quad f'(1) = 1 + \\frac{1}{2} = 1.5", explanation: "\\(f(1)\\) is positive, so the root lies to the left of \\(1\\)." }, { stepNumber: 3, description: "Apply the iteration.", workingLatex: "x_{1} = 1 - \\frac{0.30685}{1.5} = 1 - 0.20457 \\approx 0.79543", explanation: "The estimate moves left toward the root of \\(x = \\ln(3 - x)\\)." } ], finalAnswer: "\\(x_{1} \\approx 0.79543\\)." } },
  { id: "y2nm4-046", topicRef: "y2nm4", topicTitle: "Newton-Raphson 46", difficulty: "Standard", answerType: "expression", questionText: "Apply Newton-Raphson to \\(f(x) = x^{4} + x - 3\\) starting from \\(x_{0} = 1\\). Compute \\(x_{1}\\) and \\(x_{2}\\) to 5 decimal places.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["calculation"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate \\(f\\).", workingLatex: "f(x) = x^{4} + x - 3, \\quad f'(x) = 4x^{3} + 1", explanation: "Power rule on \\(x^{4}\\) gives \\(4x^{3}\\); the \\(+x\\) gives \\(+1\\)." }, { stepNumber: 2, description: "Evaluate at \\(x_{0} = 1\\) and find \\(x_{1}\\).", workingLatex: "f(1) = 1 + 1 - 3 = -1, \\quad f'(1) = 5 \\;\\Rightarrow\\; x_{1} = 1 - \\frac{-1}{5} = 1.20000", explanation: "A negative \\(f\\) over a steep positive gradient gives a controlled step to the right." }, { stepNumber: 3, description: "Compute \\(x_{2}\\).", workingLatex: "x_{2} = 1.2 - \\frac{(1.2)^{4} + 1.2 - 3}{4(1.2)^{3} + 1} = 1.2 - \\frac{0.2736}{7.912} \\approx 1.16542", explanation: "The first step slightly overshot, so the second corrects back toward the root near \\(1.1646\\)." } ], finalAnswer: "\\(x_{1} = 1.20000,\\ x_{2} \\approx 1.16542\\)." } },
  { id: "y2nm4-047", topicRef: "y2nm4", topicTitle: "Newton-Raphson 47", difficulty: "Standard", answerType: "expression", questionText: "For \\(f(x) = x^{2} - 5x + 6\\), apply Newton-Raphson starting from \\(x_{0} = 2.5\\). Find \\(x_{1}\\) and explain what happens.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["failure"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate and evaluate at \\(x_{0}\\).", workingLatex: "f'(x) = 2x - 5, \\quad f'(2.5) = 5 - 5 = 0", explanation: "The parabola \\(f(x) = (x-2)(x-3)\\) has its vertex at \\(x = 2.5\\), exactly midway between the roots — and that is where \\(f' = 0\\)." }, { stepNumber: 2, description: "Apply the failure condition.", workingLatex: "x_{1} = 2.5 - \\frac{f(2.5)}{0} \\;\\text{(undefined)}", explanation: "The tangent at the vertex is horizontal, so it never reaches the axis: the iteration breaks down immediately." } ], finalAnswer: "\\(f'(2.5) = 0\\) at the vertex; the iteration is undefined (division by zero) midway between the roots \\(2\\) and \\(3\\)." } },
  { id: "y2nm4-048", topicRef: "y2nm4", topicTitle: "Newton-Raphson 48", difficulty: "Standard", answerType: "expression", questionText: "Starting from \\(x_{0} = 2\\) for \\(f(x) = x^{3} - x^{2} - 1\\), compute \\(x_{1}\\) and \\(x_{2}\\) to 5 decimal places. State the root to 4 d.p.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["calculation"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate \\(f\\).", workingLatex: "f(x) = x^{3} - x^{2} - 1, \\quad f'(x) = 3x^{2} - 2x", explanation: "Differentiate term by term." }, { stepNumber: 2, description: "Compute \\(x_{1}\\).", workingLatex: "f(2) = 8 - 4 - 1 = 3, \\quad f'(2) = 12 - 4 = 8 \\;\\Rightarrow\\; x_{1} = 2 - \\frac{3}{8} = 1.62500", explanation: "A controlled step to the left from the start value." }, { stepNumber: 3, description: "Compute \\(x_{2}\\).", workingLatex: "f(1.625) \\approx 0.65039, \\quad f'(1.625) \\approx 4.67188 \\;\\Rightarrow\\; x_{2} = 1.625 - \\frac{0.65039}{4.67188} \\approx 1.48579", explanation: "The estimate keeps descending; the correction is shrinking." }, { stepNumber: 4, description: "Iterate to the root.", workingLatex: "x_{3} \\approx 1.46596, \\quad x_{4} \\approx 1.46557 \\;\\Rightarrow\\; \\text{root} \\approx 1.4656", explanation: "Two more steps stabilise the estimate to 4 d.p." } ], finalAnswer: "\\(x_{1} = 1.625,\\ x_{2} \\approx 1.48579\\); root \\(\\approx 1.4656\\)." } },
  { id: "y2nm4-049", topicRef: "y2nm4", topicTitle: "Newton-Raphson 49", difficulty: "Standard", answerType: "expression", questionText: "For \\(f(x) = \\sqrt{x} - 2\\), apply Newton-Raphson with \\(x_{0} = 3\\). Find \\(x_{1}\\) to 5 decimal places.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["calculation"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate the square root.", workingLatex: "f(x) = x^{1/2} - 2, \\quad f'(x) = \\frac{1}{2}x^{-1/2} = \\frac{1}{2\\sqrt{x}}", explanation: "Write \\(\\sqrt{x}\\) as \\(x^{1/2}\\) so the power rule applies." }, { stepNumber: 2, description: "Evaluate at \\(x_{0} = 3\\).", workingLatex: "f(3) = \\sqrt{3} - 2 \\approx -0.26795, \\quad f'(3) = \\frac{1}{2\\sqrt{3}} \\approx 0.28868", explanation: "\\(f(3)\\) is negative (since \\(\\sqrt{3} < 2\\)), and the gradient is shallow, so expect a large step." }, { stepNumber: 3, description: "Apply the iteration.", workingLatex: "x_{1} = 3 - \\frac{-0.26795}{0.28868} = 3 + 0.92820 \\approx 3.92820", explanation: "The shallow gradient produces a big jump toward the root \\(x = 4\\) (since \\(\\sqrt{4} = 2\\))." } ], finalAnswer: "\\(x_{1} \\approx 3.92820\\) (converging to \\(4\\))." } },
  { id: "y2nm4-050", topicRef: "y2nm4", topicTitle: "Newton-Raphson 50", difficulty: "Standard", answerType: "expression", questionText: "A root of \\(f(x) = x + \\tan x\\) lies between 2 and 2.1 (radians). Apply Newton-Raphson from \\(x_{0} = 2\\). Find \\(x_{1}\\) to 5 decimal places.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["calculation", "trigonometric"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate \\(f\\).", workingLatex: "f(x) = x + \\tan x, \\quad f'(x) = 1 + \\sec^{2} x", explanation: "The derivative of \\(\\tan x\\) is \\(\\sec^{2} x\\)." }, { stepNumber: 2, description: "Evaluate at \\(x_{0} = 2\\).", workingLatex: "f(2) = 2 + \\tan 2 \\approx -0.18504, \\quad f'(2) = 1 + \\sec^{2} 2 \\approx 6.77440", explanation: "Work in radians; \\(\\tan 2 \\approx -2.18504\\), making \\(f(2)\\) slightly negative." }, { stepNumber: 3, description: "Apply the iteration.", workingLatex: "x_{1} = 2 - \\frac{-0.18504}{6.77440} = 2 + 0.02731 \\approx 2.02731", explanation: "The estimate moves right into the bracket \\((2, 2.1)\\) where the root lies." } ], finalAnswer: "\\(x_{1} \\approx 2.02731\\)." } },
  { id: "y2nm4-051", topicRef: "y2nm4", topicTitle: "Newton-Raphson 51", difficulty: "Challenge", answerType: "expression", questionText: "For \\(f(x) = x^{3}\\), apply Newton-Raphson from \\(x_{0} = 1\\). Compute \\(x_{1}\\) and explain why convergence to the root \\(\\alpha = 0\\) is only linear.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["failure", "convergence"], workedSolution: { steps: [ { stepNumber: 1, description: "Simplify the iteration.", workingLatex: "x_{n+1} = x_{n} - \\frac{x_{n}^{3}}{3 x_{n}^{2}} = x_{n} - \\frac{x_{n}}{3} = \\frac{2}{3} x_{n}", explanation: "With \\(f' = 3x^{2}\\), the \\(\\frac{f}{f'}\\) term simplifies to \\(\\frac{x_{n}}{3}\\), so each step just scales the estimate by \\(\\frac{2}{3}\\)." }, { stepNumber: 2, description: "Compute \\(x_{1}\\).", workingLatex: "x_{1} = \\frac{2}{3}(1) = \\frac{2}{3} \\approx 0.66667", explanation: "The estimate shrinks toward \\(0\\) but only by a fixed ratio." }, { stepNumber: 3, description: "Identify the convergence rate.", workingLatex: "\\left|x_{n+1} - 0\\right| = \\frac{2}{3}\\left|x_{n} - 0\\right|", explanation: "The error is multiplied by the constant \\(\\frac{2}{3}\\) each step — first power, not squared — so convergence is linear. This happens because \\(x = 0\\) is a root of multiplicity \\(3\\), not a simple root, so the quadratic-convergence argument of Q27 fails." } ], finalAnswer: "Each step gives \\(x_{n+1} = \\frac{2}{3}x_{n}\\); the error shrinks by a constant factor, so convergence is linear because the root has multiplicity \\(3\\)." } },
  { id: "y2nm4-052", topicRef: "y2nm4", topicTitle: "Newton-Raphson 52", difficulty: "Challenge", answerType: "expression", questionText: "Prove that if \\(\\alpha\\) is a double root of \\(f\\), then Newton-Raphson converges linearly with factor \\(\\frac{1}{2}\\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["convergence", "theory"], workedSolution: { steps: [ { stepNumber: 1, description: "Write \\(f\\) in factored form.", workingLatex: "f(x) = (x - \\alpha)^{2} h(x), \\quad h(\\alpha) \\neq 0", explanation: "A double root means \\((x - \\alpha)^{2}\\) divides \\(f\\), with the remaining factor \\(h\\) nonzero at \\(\\alpha\\)." }, { stepNumber: 2, description: "Differentiate with the product rule.", workingLatex: "f'(x) = 2(x - \\alpha)h(x) + (x - \\alpha)^{2} h'(x) = (x - \\alpha)\\left[2h(x) + (x - \\alpha)h'(x)\\right]", explanation: "Factoring out \\((x - \\alpha)\\) makes the next ratio cancel cleanly." }, { stepNumber: 3, description: "Form \\(g(x) - \\alpha\\) and let \\(x \\to \\alpha\\).", workingLatex: "g(x) - \\alpha = (x - \\alpha) - \\frac{(x - \\alpha)^{2}h(x)}{(x - \\alpha)\\left[2h + (x-\\alpha)h'\\right]} = (x-\\alpha) - \\frac{(x-\\alpha)h(x)}{2h + (x-\\alpha)h'}", explanation: "One factor of \\((x - \\alpha)\\) cancels. As \\(x \\to \\alpha\\) the fraction tends to \\(\\frac{(x-\\alpha)h(\\alpha)}{2h(\\alpha)} = \\frac{x-\\alpha}{2}\\)." }, { stepNumber: 4, description: "Read off the factor.", workingLatex: "g(x) - \\alpha \\approx (x - \\alpha) - \\frac{x - \\alpha}{2} = \\frac{1}{2}(x - \\alpha)", explanation: "The new error is about half the old error, so convergence is linear with factor \\(\\frac{1}{2}\\) — slower than the usual quadratic rate because the root is not simple." } ], finalAnswer: "The error satisfies \\(x_{n+1} - \\alpha \\approx \\frac{1}{2}(x_{n} - \\alpha)\\): linear convergence with factor \\(\\frac{1}{2}\\)." } },
  { id: "y2nm4-053", topicRef: "y2nm4", topicTitle: "Newton-Raphson 53", difficulty: "Challenge", answerType: "expression", questionText: "For \\(f(x) = \\arctan x\\), applying Newton-Raphson from a sufficiently large \\(x_{0}\\) can produce divergent oscillations. Explain why intuitively.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["failure", "theory"], workedSolution: { steps: [ { stepNumber: 1, description: "Note the flattening of \\(f\\) and \\(f'\\).", workingLatex: "f(x) = \\arctan x \\to \\pm\\frac{\\pi}{2}, \\quad f'(x) = \\frac{1}{1 + x^{2}} \\to 0", explanation: "For large \\(|x|\\) the curve almost levels off near \\(\\pm\\frac{\\pi}{2}\\), so its gradient becomes tiny." }, { stepNumber: 2, description: "Write the iteration.", workingLatex: "x_{n+1} = x_{n} - \\frac{\\arctan x_{n}}{1/(1 + x_{n}^{2})} = x_{n} - \\left(1 + x_{n}^{2}\\right)\\arctan x_{n}", explanation: "Dividing by the tiny gradient multiplies the correction by \\(1 + x_{n}^{2}\\), which is huge when \\(x_{n}\\) is large." }, { stepNumber: 3, description: "Explain the oscillation.", workingLatex: "\\left|x_{n+1}\\right| > \\left|x_{n}\\right| \\;\\text{with opposite sign}", explanation: "The shallow tangent shoots far past the root \\(x = 0\\) and lands on the other side with a larger magnitude. Repeating this, the iterates flip sign and grow without bound." } ], finalAnswer: "The shallow tangent overshoots the root \\(0\\); the correction grows like \\(1 + x_{n}^{2}\\), so the iterates alternate in sign and diverge in magnitude." } },
  { id: "y2nm4-054", topicRef: "y2nm4", topicTitle: "Newton-Raphson 54", difficulty: "Challenge", answerType: "expression", questionText: "Use Newton-Raphson to find the real root of \\(f(x) = e^{x} - 4x\\) to 4 decimal places, choosing a sensible \\(x_{0}\\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["calculation", "exponential"], workedSolution: { steps: [ { stepNumber: 1, description: "Locate the roots and choose \\(x_{0}\\).", workingLatex: "f(x) = e^{x} - 4x \\;\\Rightarrow\\; \\text{roots near } 0.36 \\text{ and } 2.15", explanation: "There are two roots; targeting the larger one, take \\(x_{0} = 2\\), comfortably away from the turning point at \\(x = \\ln 4 \\approx 1.39\\)." }, { stepNumber: 2, description: "Differentiate and evaluate at \\(x_{0} = 2\\).", workingLatex: "f'(x) = e^{x} - 4, \\quad f(2) \\approx -0.61094, \\quad f'(2) \\approx 3.38906", explanation: "\\(f(2)\\) is negative, so the larger root lies to the right of \\(2\\)." }, { stepNumber: 3, description: "Compute \\(x_{1}\\) and \\(x_{2}\\).", workingLatex: "x_{1} = 2 - \\frac{-0.61094}{3.38906} \\approx 2.18027, \\quad x_{2} = 2.18027 - \\frac{0.12762}{4.84870} \\approx 2.15395", explanation: "The first step overshoots slightly; the second corrects back toward the root." }, { stepNumber: 4, description: "Iterate to 4 d.p.", workingLatex: "x_{3} \\approx 2.15329, \\quad x_{4} \\approx 2.15329 \\;\\Rightarrow\\; \\text{root} \\approx 2.1533", explanation: "Successive estimates agree to 4 d.p., so the root is \\(\\approx 2.1533\\)." } ], finalAnswer: "Root \\(\\approx 2.1533\\)." } },
  { id: "y2nm4-055", topicRef: "y2nm4", topicTitle: "Newton-Raphson 55", difficulty: "Challenge", answerType: "expression", questionText: "Use Newton-Raphson to find \\(\\ln 2\\) by solving \\(e^{x} - 2 = 0\\) starting from \\(x_{0} = 0.5\\). Give \\(x_{3}\\) to 6 decimal places.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["calculation"], workedSolution: { steps: [ { stepNumber: 1, description: "Simplify the iteration.", workingLatex: "f'(x) = e^{x} \\;\\Rightarrow\\; x_{n+1} = x_{n} - \\frac{e^{x_{n}} - 2}{e^{x_{n}}} = x_{n} - 1 + 2e^{-x_{n}}", explanation: "Dividing through by \\(e^{x_{n}}\\) turns the iteration into a tidy division-free form." }, { stepNumber: 2, description: "Compute \\(x_{1}\\).", workingLatex: "x_{1} = 0.5 - 1 + 2e^{-0.5} \\approx -0.5 + 1.21306 = 0.713061", explanation: "The estimate jumps toward \\(\\ln 2 \\approx 0.693\\)." }, { stepNumber: 3, description: "Compute \\(x_{2}\\).", workingLatex: "x_{2} = 0.713061 - 1 + 2e^{-0.713061} \\approx 0.693344", explanation: "Already correct to 3 d.p.; quadratic convergence is in full effect." }, { stepNumber: 4, description: "Compute \\(x_{3}\\).", workingLatex: "x_{3} = 0.693344 - 1 + 2e^{-0.693344} \\approx 0.693147", explanation: "\\(x_{3} \\approx 0.693147\\), which is \\(\\ln 2\\) to 6 d.p." } ], finalAnswer: "\\(x_{3} \\approx 0.693147 = \\ln 2\\)." } },
  { id: "y2nm4-056", topicRef: "y2nm4", topicTitle: "Newton-Raphson 56", difficulty: "Challenge", answerType: "expression", questionText: "Given that \\(\\alpha\\) is a root of \\(f(x) = x - \\cos x\\), show that Newton-Raphson from \\(x_{0} = 1\\) produces errors that roughly square each step.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["convergence"], workedSolution: { steps: [ { stepNumber: 1, description: "Find the root and first iterate.", workingLatex: "\\alpha \\approx 0.73908513, \\quad x_{1} = 1 - \\frac{1 - \\cos 1}{1 + \\sin 1} \\approx 0.75036387", explanation: "Apply one step from \\(x_{0} = 1\\) using \\(f'(x) = 1 + \\sin x\\); \\(\\alpha\\) is the known root for comparison." }, { stepNumber: 2, description: "Measure the first error.", workingLatex: "\\left|e_{1}\\right| = \\left|x_{1} - \\alpha\\right| \\approx 0.01128", explanation: "This is the gap between the first iterate and the true root." }, { stepNumber: 3, description: "Compute \\(x_{2}\\) and its error.", workingLatex: "x_{2} \\approx 0.73911289, \\quad \\left|e_{2}\\right| = \\left|x_{2} - \\alpha\\right| \\approx 0.0000278", explanation: "The second error is far smaller than the first." }, { stepNumber: 4, description: "Compare the errors.", workingLatex: "\\frac{\\left|e_{2}\\right|}{\\left|e_{1}\\right|^{2}} \\approx \\frac{0.0000278}{(0.01128)^{2}} \\approx 0.22", explanation: "Since \\(\\left|e_{2}\\right|\\) is roughly a constant times \\(\\left|e_{1}\\right|^{2}\\), the error squares each step — confirming quadratic convergence." } ], finalAnswer: "\\(\\left|e_{1}\\right| \\approx 0.01128\\) and \\(\\left|e_{2}\\right| \\approx 0.0000278 \\approx 0.22\\,\\left|e_{1}\\right|^{2}\\): the errors square each step." } },
  { id: "y2nm4-057", topicRef: "y2nm4", topicTitle: "Newton-Raphson 57", difficulty: "Challenge", answerType: "expression", questionText: "The polynomial \\(f(x) = x^{3} - 5x^{2} + 7x - 3\\) has a repeated root at \\(x = 1\\) and a simple root at \\(x = 3\\). Apply Newton-Raphson from \\(x_{0} = 2\\). Compute \\(x_{1}\\) and \\(x_{2}\\) to 5 decimal places and comment.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["calculation"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate \\(f\\).", workingLatex: "f(x) = x^{3} - 5x^{2} + 7x - 3, \\quad f'(x) = 3x^{2} - 10x + 7", explanation: "Differentiate term by term ready for the iteration." }, { stepNumber: 2, description: "Compute \\(x_{1}\\).", workingLatex: "f(2) = 8 - 20 + 14 - 3 = -1, \\quad f'(2) = 12 - 20 + 7 = -1 \\;\\Rightarrow\\; x_{1} = 2 - \\frac{-1}{-1} = 1.00000", explanation: "The equal values \\(f(2) = f'(2) = -1\\) make the correction exactly \\(1\\), landing the estimate precisely on the repeated root \\(x = 1\\)." }, { stepNumber: 3, description: "Attempt the next step.", workingLatex: "f'(1) = 3 - 10 + 7 = 0", explanation: "At the repeated root the gradient is zero (a repeated root is also a turning point), so the next iteration would divide by zero." }, { stepNumber: 4, description: "Comment.", workingLatex: "x_{2} = 1 - \\frac{f(1)}{f'(1)} \\;\\text{(undefined)}", explanation: "The iteration breaks down at \\(x_{1} = 1\\). Even had it not landed exactly there, convergence to a repeated root is only linear (cf. Q52)." } ], finalAnswer: "\\(x_{1} = 1\\) (the repeated root), then \\(f'(1) = 0\\) makes \\(x_{2}\\) undefined — the iteration breaks down." } },
  { id: "y2nm4-058", topicRef: "y2nm4", topicTitle: "Newton-Raphson 58", difficulty: "Challenge", answerType: "expression", questionText: "Describe a practical strategy to choose a good starting value \\(x_{0}\\) for Newton-Raphson on a given equation \\(f(x) = 0\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["strategy"], workedSolution: { steps: [ { stepNumber: 1, description: "Sketch the curve to locate roots.", workingLatex: "", explanation: "A rough sketch of \\(y = f(x)\\) (or of two curves whose intersection is the root) shows roughly where the roots are and how many there are." }, { stepNumber: 2, description: "Confirm a root by a sign change.", workingLatex: "f(a)\\,f(b) < 0 \\;\\Rightarrow\\; \\text{root in } (a, b)", explanation: "Evaluate \\(f\\) at two nearby points: opposite signs guarantee a root between them, by the change-of-sign rule." }, { stepNumber: 3, description: "Pick \\(x_{0}\\) inside the bracket, away from \\(f' = 0\\).", workingLatex: "x_{0} \\in (a, b), \\quad f'(x_{0}) \\neq 0", explanation: "Choose a start close to the root but not near a turning point, since a small \\(f'\\) gives a shallow tangent that can overshoot or diverge (cf. Q53)." } ], finalAnswer: "Sketch to locate the root, confirm it with a sign change, and pick \\(x_{0}\\) inside the interval but away from any point where \\(f'(x) = 0\\)." } },
  { id: "y2nm4-059", topicRef: "y2nm4", topicTitle: "Newton-Raphson 59", difficulty: "Challenge", answerType: "expression", questionText: "Use Newton-Raphson on \\(f(x) = \\sin x - \\frac{x}{3}\\) from \\(x_{0} = 2.5\\) (radians). Find \\(x_{1}\\) to 5 decimal places.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["calculation", "trigonometric"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate \\(f\\).", workingLatex: "f(x) = \\sin x - \\frac{x}{3}, \\quad f'(x) = \\cos x - \\frac{1}{3}", explanation: "Differentiate \\(\\sin x\\) to \\(\\cos x\\) and \\(\\frac{x}{3}\\) to \\(\\frac{1}{3}\\). Keep radians." }, { stepNumber: 2, description: "Evaluate at \\(x_{0} = 2.5\\).", workingLatex: "f(2.5) = \\sin 2.5 - \\frac{2.5}{3} \\approx -0.23486, \\quad f'(2.5) = \\cos 2.5 - \\frac{1}{3} \\approx -1.13448", explanation: "Both are negative here; \\(\\sin 2.5 \\approx 0.59847\\) and \\(\\cos 2.5 \\approx -0.80114\\)." }, { stepNumber: 3, description: "Apply the iteration.", workingLatex: "x_{1} = 2.5 - \\frac{-0.23486}{-1.13448} = 2.5 - 0.20702 \\approx 2.29298", explanation: "Negative over negative is positive, so we subtract about \\(0.21\\) and move left toward the root." } ], finalAnswer: "\\(x_{1} \\approx 2.29298\\)." } },
  { id: "y2nm4-060", topicRef: "y2nm4", topicTitle: "Newton-Raphson 60", difficulty: "Challenge", answerType: "expression", questionText: "Show that the Newton-Raphson iteration for \\(f(x) = x^{3} - a\\) is \\(x_{n+1} = \\frac{2 x_{n}^{3} + a}{3 x_{n}^{2}}\\), and apply it with \\(a = 20,\\ x_{0} = 3\\) to find \\(x_{1}\\) and \\(x_{2}\\) to 5 decimal places.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["derivation", "calculation"], workedSolution: { steps: [ { stepNumber: 1, description: "Substitute and combine over a common denominator.", workingLatex: "x_{n+1} = x_{n} - \\frac{x_{n}^{3} - a}{3 x_{n}^{2}} = \\frac{3x_{n}^{3} - \\left(x_{n}^{3} - a\\right)}{3 x_{n}^{2}}", explanation: "With \\(f' = 3x^{2}\\), write \\(x_{n} = \\frac{3x_{n}^{3}}{3x_{n}^{2}}\\) and subtract the fraction." }, { stepNumber: 2, description: "Collect the numerator.", workingLatex: "x_{n+1} = \\frac{2 x_{n}^{3} + a}{3 x_{n}^{2}}", explanation: "Since \\(3x_{n}^{3} - x_{n}^{3} = 2x_{n}^{3}\\), the required form follows — the cube-root analogue of Q7." }, { stepNumber: 3, description: "Compute \\(x_{1}\\) with \\(a = 20,\\ x_{0} = 3\\).", workingLatex: "x_{1} = \\frac{2(27) + 20}{3(9)} = \\frac{74}{27} \\approx 2.74074", explanation: "Substitute the numbers directly into the simplified iteration." }, { stepNumber: 4, description: "Compute \\(x_{2}\\).", workingLatex: "x_{2} = \\frac{2(2.74074)^{3} + 20}{3(2.74074)^{2}} \\approx 2.71467", explanation: "\\(x_{2} \\approx 2.71467\\) is very close to \\(\\sqrt[3]{20} \\approx 2.71442\\)." } ], finalAnswer: "Shown; with \\(a = 20\\): \\(x_{1} \\approx 2.74074,\\ x_{2} \\approx 2.71467\\) (compare \\(\\sqrt[3]{20} \\approx 2.71442\\))." } },
  { id: "y2nm4-061", topicRef: "y2nm4", topicTitle: "Newton-Raphson 61", difficulty: "Challenge", answerType: "expression", questionText: "An engineer solves \\(x^{2} + 3x - 7 = 0\\) using Newton-Raphson from \\(x_{0} = 2\\). Compute the positive root to 4 decimal places.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["calculation", "applied"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate \\(f\\).", workingLatex: "f(x) = x^{2} + 3x - 7, \\quad f'(x) = 2x + 3", explanation: "A simple linear derivative makes each step quick." }, { stepNumber: 2, description: "Compute \\(x_{1}\\).", workingLatex: "f(2) = 4 + 6 - 7 = 3, \\quad f'(2) = 7 \\;\\Rightarrow\\; x_{1} = 2 - \\frac{3}{7} \\approx 1.57143", explanation: "The first step moves toward the positive root." }, { stepNumber: 3, description: "Compute \\(x_{2}\\).", workingLatex: "f(1.57143) \\approx 0.18367, \\quad f'(1.57143) \\approx 6.14286 \\;\\Rightarrow\\; x_{2} = 1.57143 - \\frac{0.18367}{6.14286} \\approx 1.54153", explanation: "The correction shrinks sharply, signalling fast convergence." }, { stepNumber: 4, description: "Iterate to 4 d.p. and check.", workingLatex: "x_{3} \\approx 1.54138; \\quad \\frac{-3 + \\sqrt{37}}{2} \\approx 1.54138", explanation: "\\(x_{3}\\) is stable, and the quadratic formula confirms the exact root \\(\\frac{-3 + \\sqrt{37}}{2}\\) to 4 d.p." } ], finalAnswer: "Positive root \\(\\approx 1.5414\\)." } },
  { id: "y2nm4-062", topicRef: "y2nm4", topicTitle: "Newton-Raphson 62", difficulty: "Challenge", answerType: "expression", questionText: "Use Newton-Raphson on the equation \\(x^{4} = 10x - 5\\) from \\(x_{0} = 1\\). Find \\(x_{1}\\) to 5 decimal places.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["calculation"], workedSolution: { steps: [ { stepNumber: 1, description: "Rearrange to \\(f(x) = 0\\) form and differentiate.", workingLatex: "f(x) = x^{4} - 10x + 5, \\quad f'(x) = 4x^{3} - 10", explanation: "Move all terms to one side before differentiating." }, { stepNumber: 2, description: "Evaluate at \\(x_{0} = 1\\).", workingLatex: "f(1) = 1 - 10 + 5 = -4, \\quad f'(1) = 4 - 10 = -6", explanation: "Both are negative, so the correction will be negative and the estimate decreases." }, { stepNumber: 3, description: "Apply the iteration.", workingLatex: "x_{1} = 1 - \\frac{-4}{-6} = 1 - \\frac{2}{3} \\approx 0.33333", explanation: "Negative over negative gives a positive correction \\(\\frac{2}{3}\\), pulling the estimate down toward a root near \\(0.5\\)." } ], finalAnswer: "\\(x_{1} \\approx 0.33333\\)." } },
  { id: "y2nm4-063", topicRef: "y2nm4", topicTitle: "Newton-Raphson 63", difficulty: "Challenge", answerType: "expression", questionText: "Continuing Q62, compute \\(x_{2}\\) and comment on the iteration's behaviour.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["calculation"], workedSolution: { steps: [ { stepNumber: 1, description: "Evaluate \\(f\\) and \\(f'\\) at \\(x_{1}\\).", workingLatex: "f(0.33333) \\approx 1.67901, \\quad f'(0.33333) \\approx -9.85185", explanation: "The gradient is now large and negative, so the next step will be small." }, { stepNumber: 2, description: "Compute \\(x_{2}\\).", workingLatex: "x_{2} = 0.33333 - \\frac{1.67901}{-9.85185} = 0.33333 + 0.17043 \\approx 0.50376", explanation: "The estimate rebounds upward toward the genuine root." }, { stepNumber: 3, description: "Iterate further.", workingLatex: "x_{3} \\approx 0.50658, \\quad x_{4} \\approx 0.50659", explanation: "After the early jumpiness the sequence settles down quickly." }, { stepNumber: 4, description: "Comment.", workingLatex: "\\text{root} \\approx 0.5066", explanation: "The first iterate \\(0.33333\\) overshot below the root, but the iteration recovers and converges to \\(\\approx 0.5066\\) — a reminder that an early erratic step need not be fatal." } ], finalAnswer: "\\(x_{2} \\approx 0.50376\\); after an erratic first step the iteration recovers and converges to \\(\\approx 0.5066\\)." } },
  { id: "y2nm4-064", topicRef: "y2nm4", topicTitle: "Newton-Raphson 64", difficulty: "Challenge", answerType: "expression", questionText: "The equation \\(x = \\tan x\\) has a root near \\(x = 4.49\\) (radians). Apply Newton-Raphson from \\(x_{0} = 4.5\\). Find \\(x_{1}\\) to 5 decimal places.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["calculation", "trigonometric"], workedSolution: { steps: [ { stepNumber: 1, description: "Form \\(f\\) and differentiate.", workingLatex: "f(x) = x - \\tan x, \\quad f'(x) = 1 - \\sec^{2} x = -\\tan^{2} x", explanation: "Using \\(\\sec^{2}x = 1 + \\tan^{2}x\\), the derivative simplifies neatly to \\(-\\tan^{2}x\\)." }, { stepNumber: 2, description: "Evaluate at \\(x_{0} = 4.5\\).", workingLatex: "f(4.5) = 4.5 - \\tan 4.5 \\approx -0.13733, \\quad f'(4.5) = -\\tan^{2} 4.5 \\approx -21.50485", explanation: "Near this root \\(\\tan x\\) is large, so the gradient is steeply negative; expect a tiny step." }, { stepNumber: 3, description: "Apply the iteration.", workingLatex: "x_{1} = 4.5 - \\frac{-0.13733}{-21.50485} = 4.5 - 0.00639 \\approx 4.49361", explanation: "The very steep gradient keeps the correction small, landing right on the root near \\(4.4934\\)." } ], finalAnswer: "\\(x_{1} \\approx 4.49361\\)." } },
  { id: "y2nm4-065", topicRef: "y2nm4", topicTitle: "Newton-Raphson 65", difficulty: "Challenge", answerType: "expression", questionText: "Use Newton-Raphson on \\(f(x) = x^{3} - 4x - 9\\) from \\(x_{0} = 3\\). Find the root to 4 decimal places.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["calculation"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate \\(f\\).", workingLatex: "f(x) = x^{3} - 4x - 9, \\quad f'(x) = 3x^{2} - 4", explanation: "Differentiate term by term." }, { stepNumber: 2, description: "Compute \\(x_{1}\\).", workingLatex: "f(3) = 27 - 12 - 9 = 6, \\quad f'(3) = 23 \\;\\Rightarrow\\; x_{1} = 3 - \\frac{6}{23} \\approx 2.73913", explanation: "A steep gradient gives a controlled first step." }, { stepNumber: 3, description: "Compute \\(x_{2}\\).", workingLatex: "f(2.73913) \\approx 0.59472, \\quad f'(2.73913) \\approx 18.50851 \\;\\Rightarrow\\; x_{2} \\approx 2.70700", explanation: "The correction shrinks markedly." }, { stepNumber: 4, description: "Iterate to 4 d.p.", workingLatex: "x_{3} \\approx 2.70653, \\quad x_{4} \\approx 2.70652 \\;\\Rightarrow\\; \\text{root} \\approx 2.7065", explanation: "Successive estimates agree to 4 d.p., so the root is \\(\\approx 2.7065\\)." } ], finalAnswer: "Root \\(\\approx 2.7065\\)." } },
  { id: "y2nm4-066", topicRef: "y2nm4", topicTitle: "Newton-Raphson 66", difficulty: "Challenge", answerType: "expression", questionText: "Consider the iteration applied to \\(f(x) = (x - 1)(x - 2)(x - 3)\\). Starting from \\(x_{0} = 1.5\\), compute \\(x_{1}\\) to 5 decimal places and discuss which root the iteration ultimately finds.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["calculation"], workedSolution: { steps: [ { stepNumber: 1, description: "Expand and differentiate.", workingLatex: "f(x) = x^{3} - 6x^{2} + 11x - 6, \\quad f'(x) = 3x^{2} - 12x + 11", explanation: "Multiplying out the factors makes differentiation straightforward." }, { stepNumber: 2, description: "Evaluate at \\(x_{0} = 1.5\\).", workingLatex: "f(1.5) = (0.5)(-0.5)(-1.5) = 0.375, \\quad f'(1.5) = 6.75 - 18 + 11 = -0.25", explanation: "Read the sign carefully: \\((0.5)(-0.5)(-1.5)\\) is positive, so \\(f(1.5) = +0.375\\). The gradient is small and negative." }, { stepNumber: 3, description: "Apply the iteration.", workingLatex: "x_{1} = 1.5 - \\frac{0.375}{-0.25} = 1.5 + 1.5 = 3.00000", explanation: "The shallow gradient produces a large jump of \\(+1.5\\), landing the estimate exactly on the root \\(x = 3\\)." }, { stepNumber: 4, description: "Discuss the outcome.", workingLatex: "f(3) = 0", explanation: "Because \\(x_{1} = 3\\) is exactly a root, the iteration terminates there immediately. This shows how sensitive Newton-Raphson is near a turning point: a tiny gradient at \\(x_{0} = 1.5\\) (close to the turning point between roots \\(1\\) and \\(2\\)) flung the estimate all the way to the far root \\(x = 3\\)." } ], finalAnswer: "\\(x_{1} = 3\\); the large step from the shallow gradient lands exactly on the root \\(x = 3\\), which the iteration then keeps." } },
  { id: "y2nm4-067", topicRef: "y2nm4", topicTitle: "Newton-Raphson 67", difficulty: "Challenge", answerType: "expression", questionText: "Apply Newton-Raphson to \\(f(x) = x^{2} - \\sqrt{x} - 2\\) starting from \\(x_{0} = 2\\). Find \\(x_{1}\\) to 5 decimal places.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["calculation"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate, treating \\(\\sqrt{x}\\) as a power.", workingLatex: "f(x) = x^{2} - x^{1/2} - 2, \\quad f'(x) = 2x - \\frac{1}{2}x^{-1/2} = 2x - \\frac{1}{2\\sqrt{x}}", explanation: "Write \\(\\sqrt{x} = x^{1/2}\\) so the power rule gives \\(\\frac{1}{2}x^{-1/2}\\)." }, { stepNumber: 2, description: "Evaluate at \\(x_{0} = 2\\).", workingLatex: "f(2) = 4 - \\sqrt{2} - 2 \\approx 0.58579, \\quad f'(2) = 4 - \\frac{1}{2\\sqrt{2}} \\approx 3.64645", explanation: "\\(f(2)\\) is positive, so the root lies to the left of \\(2\\)." }, { stepNumber: 3, description: "Apply the iteration.", workingLatex: "x_{1} = 2 - \\frac{0.58579}{3.64645} = 2 - 0.16065 \\approx 1.83935", explanation: "A modest leftward step moves toward the root near \\(1.83\\)." } ], finalAnswer: "\\(x_{1} \\approx 1.83935\\)." } },
  { id: "y2nm4-068", topicRef: "y2nm4", topicTitle: "Newton-Raphson 68", difficulty: "Challenge", answerType: "expression", questionText: "Prove that, if Newton-Raphson converges, then the limit \\(\\alpha\\) satisfies \\(f(\\alpha) = 0\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["theory"], workedSolution: { steps: [ { stepNumber: 1, description: "Assume convergence and take limits.", workingLatex: "x_{n} \\to \\alpha \\;\\Rightarrow\\; x_{n+1} \\to \\alpha", explanation: "If the sequence converges to \\(\\alpha\\), then so does the shifted sequence \\(x_{n+1}\\) — they share the same limit." }, { stepNumber: 2, description: "Take limits in the iteration.", workingLatex: "\\alpha = \\alpha - \\frac{f(\\alpha)}{f'(\\alpha)}", explanation: "Letting \\(n \\to \\infty\\) in \\(x_{n+1} = x_{n} - \\frac{f(x_{n})}{f'(x_{n})}\\), using continuity of \\(f\\) and \\(f'\\) with \\(f'(\\alpha) \\neq 0\\)." }, { stepNumber: 3, description: "Deduce \\(f(\\alpha) = 0\\).", workingLatex: "0 = -\\frac{f(\\alpha)}{f'(\\alpha)} \\;\\Rightarrow\\; f(\\alpha) = 0", explanation: "Cancelling \\(\\alpha\\) from both sides forces the fraction to vanish; since \\(f'(\\alpha) \\neq 0\\), this requires \\(f(\\alpha) = 0\\). So the limit is genuinely a root." } ], finalAnswer: "Taking limits gives \\(\\alpha = \\alpha - \\frac{f(\\alpha)}{f'(\\alpha)}\\), hence \\(f(\\alpha) = 0\\): the limit is a root of \\(f\\)." } },
  { id: "y2nm4-069", topicRef: "y2nm4", topicTitle: "Newton-Raphson 69", difficulty: "Challenge", answerType: "expression", questionText: "Use Newton-Raphson to find the real root of \\(f(x) = x^{3} + x - 1\\) to 5 decimal places, starting from \\(x_{0} = 0.5\\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["calculation"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate \\(f\\).", workingLatex: "f(x) = x^{3} + x - 1, \\quad f'(x) = 3x^{2} + 1", explanation: "Note \\(f'(x) = 3x^{2} + 1 > 0\\) everywhere, so there is exactly one real root and no turning-point trouble." }, { stepNumber: 2, description: "Compute \\(x_{1}\\).", workingLatex: "f(0.5) = 0.125 + 0.5 - 1 = -0.375, \\quad f'(0.5) = 1.75 \\;\\Rightarrow\\; x_{1} = 0.5 - \\frac{-0.375}{1.75} \\approx 0.71429", explanation: "A negative \\(f\\) over a positive gradient steps the estimate to the right." }, { stepNumber: 3, description: "Compute \\(x_{2}\\).", workingLatex: "x_{2} = 0.71429 - \\frac{f(0.71429)}{f'(0.71429)} \\approx 0.68318", explanation: "The first step overshot slightly; the second corrects back down." }, { stepNumber: 4, description: "Compute \\(x_{3}\\) and conclude.", workingLatex: "x_{3} = 0.68318 - \\frac{f(0.68318)}{f'(0.68318)} \\approx 0.68233", explanation: "\\(x_{3}\\) is stable to 5 d.p., so the real root is \\(\\approx 0.68233\\)." } ], finalAnswer: "Root \\(\\approx 0.68233\\)." } },
  { id: "y2nm4-070", topicRef: "y2nm4", topicTitle: "Newton-Raphson 70", difficulty: "Challenge", answerType: "expression", questionText: "Newton-Raphson is used to find a root of \\(f(x) = x^{3} - 2x + c\\) for a parameter \\(c\\). Starting from \\(x_{0} = 0\\), show that \\(x_{1} = c/2\\), and discuss what happens to the iteration for \\(c = 0.5\\) and \\(c = 2\\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["parameter", "calculation"], workedSolution: { steps: [ { stepNumber: 1, description: "Differentiate and evaluate at \\(x_{0} = 0\\).", workingLatex: "f'(x) = 3x^{2} - 2, \\quad f(0) = c, \\quad f'(0) = -2", explanation: "Substituting the start value isolates the dependence on the parameter \\(c\\)." }, { stepNumber: 2, description: "Show \\(x_{1} = c/2\\).", workingLatex: "x_{1} = 0 - \\frac{c}{-2} = \\frac{c}{2}", explanation: "The first iterate is exactly half the parameter, independent of anything else." }, { stepNumber: 3, description: "Case \\(c = 0.5\\).", workingLatex: "x_{1} = 0.25 \\;\\to\\; 0.25862 \\;\\to\\; 0.25865 \\;\\to\\; \\ldots", explanation: "With \\(c = 0.5\\) the iteration settles quickly to the small real root \\(\\approx 0.25865\\): a well-behaved, convergent case." }, { stepNumber: 4, description: "Case \\(c = 2\\).", workingLatex: "x_{1} = 1, \\; f(1) = 1,\\ f'(1) = 1 \\;\\Rightarrow\\; x_{2} = 0, \\; x_{3} = 1, \\ldots", explanation: "With \\(c = 2\\) the iteration falls into a 2-cycle \\(0 \\to 1 \\to 0 \\to 1 \\to \\cdots\\): it never converges and never reaches the only real root (near \\(-1.7693\\)). This shows how a parameter change can switch the method from convergent to permanently cycling." } ], finalAnswer: "\\(x_{1} = \\frac{c}{2}\\). For \\(c = 0.5\\) the iteration converges to \\(\\approx 0.2587\\); for \\(c = 2\\) it enters a 2-cycle \\(0 \\leftrightarrow 1\\) and never converges to the real root near \\(-1.7693\\)." } },
];
